quests[25463] = { id = 25463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Silvia", description = "A Highborne mage named Estulan, estranged from his surviving brothers, has built a tower to the east where he trains young night elves in arcane magic.\n\nWere it not for Lady Tyrande's recent mercy towards his kind, his execution would be my duty under the law. He will be watched closely, but I will not deny aid to my Sentinels simply out of pride.\n\nI've sent Silvia ahead to the Tower of Estulan to begin an offensive against the ogres infesting the nearby forest. Report to her for further orders.", completion = "Good to see you here. Estulan is being...difficult. We're going to have to deal with these ogres for Lady Shandris on our own until he decides to deal with us.", objectives = "Report to Silvia at the Tower of Estulan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25464] = { id = 25464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Return of Baron Geddon", description = "Ragnaros is not the only powerful elemental that has re-emerged into our world.\n\nThe dreaded Baron Geddon is leading the onslaught and we must put an end to this rampage.\n\nThe Flameseer's Staff has proven powerful.  Perhaps it is powerful enough to weaken him to the point where our arch druids can bind him where he stands.\n\nGo, {name} and be careful.  Baron Geddon is a vengeful and treacherous being.", progress = "Is it done yet, {name}?", completion = "Well done, {name}.  We cannot afford to lose any further ground in Hyjal.\n\nBy stopping Baron Geddon we will have dealt a huge blow to the enemy.", objectives = "Channel the Flameseer's Staff to weaken Baron Geddon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25465] = { id = 25465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still With The Zapped Giants", description = "Hey pal! I'm still working on a variant of a gnomish shrinking ray, using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I'd like for you to try it out on some of the sea giants along the coast here.  You should find miniaturization residue on them after you shrink them - bring me back some!", progress = "I had to tweak the thing to stop working on mountain giants. Even though I wasn't the one running around zapping things, those night elves beat the copper out of me after they found those guys shrunk.", completion = "Splendifimous!  Not only am I glad to see that you've returned with the residue, but also with all your major appendages intact!  That is, well, there was never any danger in using the Ultra-Shrinker, now was there!\n\nI do appreciate your effort on my behalf, {name}.  Truly, you are a friend to goblins everywhere.  Accept this as a token of my appreciation!", objectives = "Use Zorbin's Ultra-Shrinker to zap Shore Striders and collect 6 Miniaturization Residues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25466] = { id = 25466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even More Fuel for the Zapping", description = "If I bet against my own better judgment and stay to run an engineering shop along the Forgotten Coast, I will need to deal with these pesky elementals.  Curse the powers of elementalism unchecked, I say!\n\nFortunately for me, and now for you my hopeful agent provocateur, the elementals represent an ideal source of raw power for my Ultra-Shrinker refinement - give them the what-for I say!  When doing this though, be sure to save me the water elemental cores!", progress = "While I could bore you with the technical details of the utility behind elemental cores, I will instead tempt you to completion of this important task by offering valuable coin and prizes for doing so.  Yon verily, are you finished?", completion = "Scrumdillyriffic!  These cores will keep me working for some time.  Add to that the benefit of there now being fewer elementals along the coast, and I might no longer cry myself to sleep at the prospect of having set up shop in perhaps the worst place imaginable!\n\nThank you, {name}, for your efforts on my behalf.  While it certainly straps me financially to do this, allow me to show you some gratitude you may understand and appreciate... loot!", objectives = "Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25467] = { id = 25467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kliklak's Craw", description = "You are pleasantly surprised to find that after being mangled and masticated by a sea crab, this map is still quite legible.\n\nIt clearly indicates that a footlocker was buried in the Kelp'thar Forest behind a gigantic mollusk.\n\nA well-drawn sketch on the back of the map shows that the owner, along with his key, was eaten by an overgrown crustacean named Kliklak.", progress = "The footlocker's keyhole is encrusted with barnacles, but may still be operable.", completion = "The satisfying sound of a chest unlocking is followed by the sight of once-hidden treasure.", objectives = "Obtain the Corroded Key from Kliklak to unlock the Half-buried Footlocker in the Kelp'thar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25468] = { id = 25468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Faerie Dragons", description = "You wouldn't know it from looking at them, but the lovely faerie dragons that inhabit this forest can be truly fearsome if trained properly. They can do amazing things to magical energy...absorb it, redirect it, even nullify it entirely.\n\nThey're nearly harmless alone, but in large numbers, they can have a stunning effect on a battle. You can find some in the fields to the northwest, but be careful, the Horde is nearby.", completion = "Aren't they adorable? The babies are even cuter.", objectives = "Use Jesana's Faerie Dragon Call to rally 10 Sprite Dragons or Sprite Darters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25469] = { id = 25469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Mountain Giants", description = "The mountain giants are our most powerful allies of the forest. They're carved from the land itself.\n\nNot many of our enemies are willing to fight off a walking hillside. It only takes a few of these to turn the tide of a battle completely.\n\nThe mountain giants here have been afflicted by some illness lately, but I've seen a healthy group of them to the southwest.", completion = "Excellent!\n\n{name}, you've helped bolster our forces here, and you've saved many of these forest creatures from the Horde as well. With our army now ready, Feathermoon will stand against all threats, Horde or otherwise!\n\nOn behalf of Lady Feathermoon, I'd like to award you with this weapon, fit for a Sentinel.", objectives = "Use Jesana's Giant Call to rally 5 Mountain Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25470] = { id = 25470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Of Da Tigers", description = "Remember de frogs ya made into me eyes and ears? Well, dey've found somethin' interestin'.\n\nOn an island to de southeast, dey've spied a tiger even de other cats seem to fear. Dis tiger, I've never seen anythin' like it.\n\nIt hunts wit' da instincts of a cat, but de mind of a person. It could be a powerful spirit and a strong ally.\n\nI'll be callin' down the spirit o' the tiger upon ya. Use its gifts to locate this cat and challenge it. See if ya can win its aid in our battle for the isles.", objectives = "While imbued with the Spirit of the Tiger, lure the Tiger Matriarch out of hiding and use your new abilities to best it in combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25471] = { id = 25471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Across the Great Divide", description = "We will need to press deeper into Vashj'ir if we want to uncover what the naga are doing here.\n\nGo to the Lightless Reaches, the giant chasm bordering the Kelp'thar Forest to the west.  If you look across it, you should see a cluster of plant-life surrounding the entrance to Damplight Chamber.\n\nOnce you're inside the cave, it's a bit of a ride up until you break surface, but I have friends there that should provide you a warm welcome.", completion = "Ello, mon! You look a bit more capable then most of dem coming through here.\n\nCome rest a bit. Make yaself at home.", objectives = "Speak to Farseer Gadra in the Damplight Chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25472] = { id = 25472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flameseer's Staff", description = "A powerful artifact known as the Flameseer's Staff was lost during the initial onslaught by the enemy forces.  It was an ancient bone staff that granted its wielder power over the elements of fire.\n\nIts fragments litter the area around us.  Find them and bring them to Malfurion.  Perhaps the artifact's power will still be of use.", progress = "Yes, {name}?", completion = "Excellent, {name}.  This will be a great weapon against the enemy forces.", objectives = "Obtain 8 Bone Staff Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25473] = { id = 25473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'Cola", description = "Sassy's been riding me to supply some Kaja'cola for the party that's being thrown in your honor later today.\n\nOops, was it supposed to be a surprise? You didn't hear it from me!\n\nAnywho, with production down these last few days, this is all that I managed to get made. Would you take it to her?", progress = "<Sassy eyes the six-pack warily, as if she expects it to explode as soon as you hand it to her.>\n\nWe need more Kaja'Cola than this!\n\nI swear I'm going to fire Dampwick if I don't kill him first!", completion = "Just so you know, you'll find Kaja'Cola all over town. It's the Bilgewater Cartel's best-selling product of all time!\n\nJust remember, image is everything if we're going to get you promoted to Trade Prince! No, wait, profits are everything! Explosions are a close second! Then, image!", objectives = "Deliver the Six-Pack of Kaja'Cola to Sassy Hardwrench at KTC Headquarters on Kezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25474] = { id = 25474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More, With Eeling [DEPRICATED]", description = "Eels are among the creepiest of Azeroth's creatures.\n\nSure, there are those who pretend that they don't mind them - and others who actually claim to favor them.\n\nThey are lying.\n\nTruth be told, no one likes eels. Eels don't even like eels.\n\nAzeroth would be a better place if no one ever had to envision an eel slithering out from the murky depths and biting them.\n\nIn the face.", objectives = "Kill 15 of any Eel in the Kelp Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25475] = { id = 25475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find OOX-22/FE!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-22/FE is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"", objectives = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25476] = { id = 25476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue OOX-22/FE!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the main road!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", completion = "Oh, YOU'RE the great savior of OOX-22/FE!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance {name}, my robots and I are in your debt!", objectives = "Escort OOX-22/FE to safety, then report to Oglethorpe Obnoticus in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25477] = { id = 25477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better Late Than Dead", description = "Greetings, friend.\n\nIt is good to see that you survived your battle in one piece.\n\nWhile Erunak tries to scry a place of safety for us all, I shall assist you in securing a less strenuous means of transport.\n\nI have prepared this baitstick to use near a sea turtle. It is crude, but it should serve to bring one under your control.\n\nOnce you've become comfortable with the animal, simply guide it back here to me.", progress = "Were you able to tame a sea turtle, {name}?", completion = "How unfortunate...\n\nWell, all things considered, it is good to see that you made it back unharmed.", objectives = "Use Moanah's Baitstick on a Speckled Sea Turtle and ride it back to her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25478] = { id = 25478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Summit", description = "We are staging a relief effort at Westreach Summit for all of Thousand Needles. The goblin, Dyslix Silvergrub, will lend you my wind rider to safely get you there. Speak with Kanati Greycloud when you land.\n\nYou must go quickly if lives are to be saved!", completion = "Nyse sent you? Good! We need your help, now!", objectives = "Borrow a wind rider from Dyslix Silvergrub and speak with Kanati Greycloud at Westreach Summit in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25479] = { id = 25479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To New Thalanaar", description = "We are staging a relief effort at New Thalanaar for all of Thousand Needles. The goblin, Dyslix Silvergrub, will lend you my hippogryph to safely get you there. Speak with Caryssia Moonhunter when you land.\n\nYou must go quickly if lives are to be saved!", completion = "Thyssiana sent you? Good! We need your help, now!", objectives = "Borrow a hippogryph from Dyslix Silvergrub and speak with Caryssia Moonhunter at New Thalanaar in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25480] = { id = 25480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dance Of De Spirits", description = "De time has come to start thinkin' about when to make our move. Champion Uru'zin tells me his men be ready. You and Vanira done good work gatherin' information on de enemy and findin' us new allies.\n\nNow, we read de omens. We find out when to launch de attack.\n\nFind Witch Doctor Hez'tok near the circle of ritual dancers. He be startin' de ritual as soon as ya be ready.", objectives = "Talk to Witch Doctor Hez'tok near the circle of ritual dancers outside Sen'jin Village when you're ready to consult the omens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25481] = { id = 25481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To New Thalanaar", description = "We are staging a relief effort at New Thalanaar for all of Thousand Needles. Seyala Nightwisp will lend you my hippogryph to safely get you there. Speak with Caryssia Moonhunter when you land.\n\nYou must go quickly if lives are to be saved!", completion = "Falfindel Waywarder sent you? Good! We need your help, now!", objectives = "Borrow a hippogryph from Seyala Nightwisp and speak with Caryssia Moonhunter at New Thalanaar in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25482] = { id = 25482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Holiday Dungeon - Headless Horseman - 1st" }
quests[25483] = { id = 25483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Holiday Dungeon - Coren Direbrew - 1st" }
quests[25484] = { id = 25484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Holiday Dungeon - Ahune - 1st" }
quests[25485] = { id = 25485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Holiday Dungeon - Crown Chemical - 1st" }
quests[25486] = { id = 25486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem are Coming", description = "This is going to take a while, but I'm sure we'll beat them back.\n\nYou're more good to Thousand Needles elsewhere. We have reports that the gnomes and goblins out on the flooded salt flats somehow survived on a giant barge! Rendow is on the dock. She'll get you a boat to go there.\n\nMind helping us out a little on your way to her?", completion = "A boat? Yes, you can have this last one.", objectives = "Slay 7 Grimtotem Marauders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25487] = { id = 25487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem are Coming", description = "The cowardly Grimtotem have attacked us by surprise when we were least prepared!\n\nYou will be of most help to Thousand Needles elsewhere, {class}. We have heard rumors that the goblins and gnomes somehow survived in a giant barge out on the salt flats.\n\nMotega Firemane is at the base of the summit. He can get you a canoe to take you there.\n\nDo you mind helping us fight off the Grimtotem on your way to him?", completion = "You want a canoe to go out to the salt flats? But, surely the race track has been destroyed?!\n\nNonetheless, for your bravery, you will have the last one!", objectives = "Slay 7 Grimtotem Pillagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25488] = { id = 25488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two If By Boat", description = "Are you ready to go, {class}? One of the sentinels will take you out to the Mirage Raceway.\n\nIf there's anyone left alive out there, please help them.\n\nGoddess watch over you!", completion = "YES?! Do you see me interrupting your fascinating argument?\n\nNo... no, please, go ahead. I'm sure that your interruption is about something very important. More important than dealing with the survival of everyone here, in fact.\n\n<Fizzle taps his foot impatiently.>", objectives = "Speak with Fizzle Brassbolts at Fizzle & Pozzik's Speedbarge in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25489] = { id = 25489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two If By Boat", description = "Are you ready to go, {class}?\n\nOne of our braves will row you out to the Mirage Raceway. If anyone has survived out there, they'll desperately need your help.\n\nMay the Earth Mother smile upon you.", completion = "Heya, kid, I'll be right with ya. Just gotta shut this gnome twerp up first.", objectives = "Speak with Pozzik at Fizzle & Pozzik's Speedbarge in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25490] = { id = 25490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smashing Through Ashes", description = "{name}, these fiends from the Twilight's Hammer are attempting to scourge this whole mountain clean of all life. Even now they trail behind this inferno, leaving death and ash in their wake.\n\nArch Druid Hamuul Runetotem is behind the fires, trying to salvage the wilderness before it's blotted permanently from the map. Travel southeast, through The Inferno and down the road beyond. Find and aid the Arch Druid.\n\nOn your way there, clear the roads by killing any Charbringers that you find.", progress = "Have you made any progress clearing the road to this shrine?", completion = "Very good. The Twilight's Hammer must be sent the message that we will never give up.", objectives = "Slay 8 Charbringers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25491] = { id = 25491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durable Seeds", description = "This land has been scourged by fire, but it may yet renew itself.\n\nSome seeds deep in the soil may have withstood the scorching heat here in The Flamewake. These durable plants are the key to this forest's regrowth. Please, collect some of these seedlings for me.", progress = "I suspect life still struggles beneath the ash. What were you able to find?", completion = "<The Arch Druid inspects the seedlings.>\n\nThese seedlings have survived an apocalypse. Even a handful hold great power. Life always replenishes itself, often stronger than before.\n\nOnce the way is clear, we will use these to perform a miracle on this mountain, {name}. You will see.", objectives = "Gather 10 Hyjal Seedlings from piles of Scorched Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25492] = { id = 25492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebreak", description = "In their efforts to decimate Hyjal, Twilight's Hammer has elementals scouring the earth in the wake of the fire.\n\nThey're pulverizing the soil, rooting around in the ash, digging up any scrap of plantlife that survived and destroying it. It's like they're paving the way for... I don't even want to imagine.\n\nStop them before Hyjal is devoid of life. Kill the lava surgers!", completion = "Good work, {name}. There's a chance the forest will recover from this yet.\n\nNow, there's something else I need you to take care of for me...", objectives = "Slay 10 Lava Surgers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25493] = { id = 25493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Bait", description = "I was stunned to discover that Twilight's Hammer had located - and imprisoned - the great turtle ancient Tortolla. As we speak he is chained above the murky waters of the Ashen Lake.\n\nFreeing Tortolla from his bonds will not be easy. But we will take it one step at a time.\n\nHead into the Flamewake and collect for me heaps of core hound entrails. I will explain why later.\n\nAnd beware of Nemesis the Usurper while you are there! His time will come, but we are not yet prepared.", progress = "Have you collected the innards?\n\nCore hounds are not native to this part of the world, they accompanied Twilight's Hammer from the nether regions of the earth. Do not trouble yourself over their elimination.", completion = "Very good. We will need these to act as bait while they are still warm.\n\nHere is my plan...", objectives = "Collect 4 heaps of Core Hound Entrails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25494] = { id = 25494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Champion's Collar", description = "This little guy is a true menace now, isn't he?\n\nWe're going to have to give him a nice spiked collar if he's going to be a fighting pup.\n\nThe basilisk matriarch has made her lair off of the road to Winterspring.  Bring me her spiked hide and we'll fashion a collar for our little killer here.", progress = "Did you get it?", completion = "Excellent!  Our pup is ready for a fight.", objectives = "Obtain the Spiked Basilisk Hide from the Spinescale Matriarch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25495] = { id = 25495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparin' For Battle", description = "Vol'jin be gatherin' his gear and readyin' de warriors. He ask me to tell ya to meet with him an' Vanira on de island to de east.\n\nFrom dere, he and de warriors will launch de attack on Zalazane. May de ancestors go wit' you, {name}. Without ya, dis campaign would only be a shadow of what it become. Speak to Handler Marnlek, just to de south, an' he give you a bat to fly out to de stagin' area.", sourceObjective = "Speak to Handler Marnlek for a flight to the staging area. Meet Vol'jin on the island east of the war camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[25496] = { id = 25496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grudge Match", description = "I don't know if you've picked up on this, but there's a bit of a rivalry between the ogre members of the Twilight's Hammer and the rest of us.\n\nFor me... it's personal.\n\nThis one ogre called Gromm'ko has a pet raptor named \"Butcher.\"  He's taken out the last three of my corehound pups.\n\nI think this last one will fare differently.  He's got a real killer's instinct.\n\nGo to the Seat of the Chosen and challenge Gromm'ko to a match between our two beasts.  Humiliate him for me, {name}damus.", completion = "That's how it's done!", objectives = "Challenge Gromm'ko at the Seat of the Chosen in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25497] = { id = 25497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back in the Saddle", description = "Our situation is growing a bit desperate, {race}.\n\nWe must focus our attention on the naga and their prisoners, but it would be folly to do so without being prepared, and down here that means finding a way to travel more quickly.\n\nThese sharks are clearly fond of sea turtle. Let's see if we can turn that into our advantage.", objectives = "Use 6 Turtle Meat to create shark bait.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25498] = { id = 25498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Bait", description = "<Erunak speaks as he places the turtle meat into a porous sack.>\n\nReady yourself, {name}. There's no telling how this might end up, but we don't have much choice if we are to rescue your friends.\n\nTake this sack and use it at the sunken anchor southeast of here. Once you've attracted a shark, do your best to ride it back to me here.\n\nIf you can do that, you will have a most intimidating means of transportation.", objectives = "Use the Shark Bait at the Sunken Anchor and ride the shark to Erunak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25499] = { id = 25499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agility Training: Run Like Hell!", description = "Before we go any further, we're going to have to get you into shape.\n\nDevotion to the Old Gods is not going to save you when some emerald dragon comes chasing after you.  You need to be fleet of foot, if you catch my drift.\n\nEnough said.  We'll summon your trainer... your job is to run away from him without leaving this camp.\n\nGo!", completion = "Oh.  You're still alive.\n\nNot bad.", objectives = "Run away from the Blazing Trainer within the Forge of Supplication for 1 minute.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25500] = { id = 25500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words for Delivery", description = "Here we go.  This is the speech, {name}!\n\nIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes.  Never has a finer speech been written!\n\nTurn this in to Captain Tread Sparknozzle and see if there's anything else he needs of you.", objectives = "Give the speech to Captain Tread Sparknozzle at Steelgrill Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25501] = { id = 25501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poaching for Dummies", description = "A new face around here, huh? You're in luck, making coin's easy thanks to my butcherbots. You go out and hunt some scorpids, some hyenas, maybe a few basilisks, set the butcherbot down, and let him do his thing! I've programmed him to extract all the valuable parts and place it safely in his hopper.\n\nIf you're interested, take him out to the northwest near Sandsorrow Watch first. Just bring him back once he's full and I'll pay you for the contents.", objectives = "Use the Butcherbot on the corpse of 20 Glasshide Basilisks, Scorpid Tail Lashers, or Blisterpaw Hyenas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25502] = { id = 25502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepping the Soil", description = "The Arch Druid has tasked me with setting up a series of flamewards around the perimeter of the area. Once these are active, we can prevent further attacks from the fire elementals that left this valley in ruins.\n\nThese will also protect and nourish the soil for whatever Hamuul has planned.\n\nIt's time to begin. Find one of the five flamewards I've marked on your map, activate it, and defend it from counterattack until its magic kicks in. It won't take more than a minute.", completion = "That's good! Between your work and the work of a few others, that valley is secure from a counter-attack.\n\nI've done all I can. It's all up to you and the Arch Druid now.", objectives = "Activate and defend a Flameward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25503] = { id = 25503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfin's Booty", description = "<A torn page precedes the latest entry, which reads:>\n\nOur self-proclaimed king will stop at nothing to acquire my family fortune. He has threatened and harassed me to no end.\n\nI can't take it anymore!\n\nI've buried the treasure and fed the map to Blackfin.\n\nThat should keep my cousin's grubby little mitts off of our precious heirlooms!", progress = "You've discovered Gilblingle's family treasure!", completion = "This item was highly prized by the local gilblin population - even coveted by King Gurboggle, himself!", objectives = "You must slay the orca, Blackfin, to retrieve Gilblingle's Map.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25504] = { id = 25504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Me a Favor?", description = "Hello there. Pleased to meet you! I'm Fizzle Brassbolts. Welcome to my Speedbarge.\n\nI share your concerns about helping all of Thousand Needles. It's my firm belief that the Speedbarge is the best hope for the entire region.\n\nPerhaps you could help us out a little bit here? I'll make sure that you're equipped with what you need to tackle everything else.\n\nAs to that, if you could just run this list of parts over to Jinky Twizzlefixxit in her shop, you'll be well on your way.", progress = "Is that the list of parts, finally? I've been waiting all day for that!", completion = "<Jinky eyes the list of parts and spits!>\n\nI don't have even half of that stuff!", objectives = "Deliver the List of Parts to Jinky Twizzlefixxit at Fizzle & Pozzik's Speedbarge in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25505] = { id = 25505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Me a Favor?", description = "Hey there, {name}. I'm Pozzik, world-renowned rocket car pilot. Welcome to my Speedbarge.\n\nI share your concerns about helping all of Thousand Needles. It's my firm belief that the Speedbarge is the best hope for the entire region.\n\nPerhaps you could help us out a little bit here? I'll make sure that you're equipped with what you need to tackle everything else.\n\nAs to that, if you could just run this list of parts over to Razzeric in his shop, you'll be well on your way.", progress = "Is that my list of parts from Pozzik?", completion = "Heya, pal, mind if I take a look at that list?\n\n<Razzeric nearly spits!>\n\nWhat's Pozzik thinking? He knows that I don't have even half of that stuff!", objectives = "Deliver the List of Parts to Razzeric at Fizzle & Pozzik's Speedbarge in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25506] = { id = 25506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea-Food Chain", description = "Our time here draws to a close.\n\nI must find my way across the chasm and discover the purpose behind the naga activities here.\n\nIf you are to follow me, you would be wise to conclude your search for a suitable mount first.\n\nSearch the area north of here and find a puffer hatchling. Once you've caught one, bring it to the trench to the west. I will prepare everything you need there.", objectives = "Find a Puffer Hatchling in Gnaws' Boneyard and bring it to the Abyss near the Holding Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25507] = { id = 25507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hell's Shells", description = "Fresh and stinking, these innards will prove to be irresistible for Nemesis, the befouled turtle god created by Twilight's Hammer.\n\nNemesis must eventually be destroyed, but first, we must collect a piece of his fiery armored shell. With it, we'll be able to work some magic to free the true ancient.\n\nGo into the Flamewake and drop this bait near Nemesis. It will distract him. Pry off a piece of his shell... then run, if you hope to survive the encounter.", progress = "Nemesis is a molten ball of fury protected by a stony shell of pure hatred.\n\nHis time will come.", completion = "<The Arch Druid takes the shell from you with surprising reverence.>\n\nNemesis is an instrument of evil, but he was forged from a shell fragment of the true Ancient.\n\nWe will exploit this connection.", objectives = "Use the Heap of Core Hound Innards near Nemesis to distract him. Collect a Nemesis Shell Fragment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25508] = { id = 25508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brilliant Idea", description = "I have a brilliant idea!\n\nLets stop the playthrough here.  There's not much more to see at the moment anyway.\n\nThanks for helping!" }
quests[25509] = { id = 25509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Physical Training: Forced Labor", description = "Training to join our ranks is not pleasant.  Why should it be?\n\nThe path to serve the Old Gods is long, painful, and soul-harrowing.  Consider this your first step.\n\nTake this pick and break the lodestone deposits found in the gorge.\n\nNo, we don't need any of the ore.  This is purely for your benefit.", completion = "Very well.  You're at least competent enough to figure out which way the pointy end of the pick goes.", objectives = "Break 5 Darkwhisper Lodestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25510] = { id = 25510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortolla Speaks", description = "<The Arch Druid fills the shell fragment with water, which boils instantly. He adds a bundle of herbs and closes his eyes in a silent prayer.>\n\n{name}, Tortolla the turtle ancient is ageless, a part of this world since the time of the titans. He speaks a language older than our understanding.\n\nDrink this and find a place of calm within yourself. You will be able to understand the language of Tortolla. Go to him now, in the Ashen Lake. Earn the ancient's trust. The fate of Hyjal hinges on this.", completion = "{race}.\n\nThis tongue. Is not yours.\n\nWhat do you want ... tormentor?", objectives = "Go to Tortolla, the turtle ancient, at the Ashen Lake in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25513] = { id = 25513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: Grudge Match!", description = "It seems we have a special request! I have here a note from one Kelsey Steelspark, requesting to enter the cage and settle a dispute.\n\nShe's asked for you to be her partner, {name}. A fan of your previous victories? Or perhaps you're acquainted outside the ring?\n\nI wouldn't back down now if I were you. This is the grand finale...", progress = "Stop wasting my time. Enter and fight!", completion = "Fantastic. I might challenge you to a duel myself someday.", objectives = "Defeat Megs Dreadshredder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25514] = { id = 25514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Bonds", description = "From the deep...\nA realm of darkness and fire.\nGrasping in my slumber.\n\nI am ensnared, {race}.\n\nShadows lurk in the rods of fire beside me.\nSlay them.\nThat I may be free again.", progress = "They are not of this world.\n\nThey know neither pity nor fear.", completion = "<Tortolla quivers and shakes debris free from his great back.>\n\nYou...\nAre not like the others.\n\nI am free once again.\n\nThe others...\nWill pay.", objectives = "Disable the two Rods of Subjugation that bind Tortolla.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25515] = { id = 25515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down in the Deeps", description = "<Jinky rolls up her sleeves and slicks back her hair while eyeing you up and down.>\n\nFine, if Fizzle wants you to have your own boat, the first thing we'll need is parts. Guess who gets to go get them?\n\n<Jinky smiles as she points downward and then grabs you a spare diving helm and flippers.>\n\nThat's right, <brother/sister>. You get to go down into the deeps and salvage what rocket car parts you can find at the Raceway Ruins.", progress = "I'm not punching the timecard on this one until you get me everything that's on that parts list.", completion = "This'll do for a start.", objectives = "Collect 10 Rocket Car Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25516] = { id = 25516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down in the Deeps", description = "Well, friend, if Pozzik wants you to have your own boat, the first thing we're going to need is parts. Now guess who gets to go get them?\n\n<Razzeric smiles as he points downward and then grabs you a spare diving helm and flippers.>\n\nI'm afraid so, {name}. You get to go down into the deeps and salvage what rocket car parts you can find at the Raceway Ruins.", progress = "We can get started as soon as you get everything that's on the list.", completion = "This is a great start!", objectives = "Collect 10 Rocket Car Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25517] = { id = 25517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Fight!", description = "Those no-good, smelly, green in the gills goblins have got it coming!\n\nI want you to go into the Speedbarge Bar, order a bottle of grog, and hit one over the head with it!\n\nShow them that we're not going to take any more of their insolence, {name}!", completion = "That's the spirit! You're a real credit to the Alliance!\n\nYou know, you can go back in there and do that anytime you feel like it. I highly encourage you to do so!", objectives = "Start a bar fight!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25518] = { id = 25518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Fight!", description = "Those pint-sized, goober-looking, no-explosion gnomes have got it coming!\n\nI want you to go into the Speedbarge Bar, order a bottle of grog, and hit one over the head with it!\n\nShow them that we're not going to take any more of their arrogance, {name}!", completion = "Yes! You're a real credit to the Horde!\n\nYou know, you can go back in there and do that anytime you feel like it. I highly encourage you to do so!", objectives = "Start a bar fight!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25519] = { id = 25519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of Tortolla", description = "My children.\nThey lie below.\nIn silt and sand.\n\nThe others corrupt them.\nDarken them within their shells.\n\nSlay the others.\nDestroy the corruptors.\nSave them...", progress = "My children.\nTell me they will be born free...", completion = "{race}.\nYou are not like the others.\n\nBraver. Stronger.\nA part of this world...\n    and not the shadow that came before.\n\nThank you.", objectives = "Slay 6 Deep Corruptors attacking Tortolla's Eggs in the Ashen Lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25520] = { id = 25520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Awakens", description = "I slumbered in the healing silt of Hyjal.\nI slept until the world broke open.\nWhen the others came, I was not ready.\n\nI am ready now, {race}.\n\nMy children and I. Slow to anger.\nBut our wrath is final.\n\nTell those who sent you that we are prepared for war.\n\nThe others will be cast from the mountain.", completion = "{name}!\n\nYou were able to earn the ancient's trust?\n\nWonderful! We are one step closer to taking back this mountain...", objectives = "Return to Arch Druid Hamuul Runetotem at the Sanctuary of Malorne in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25521] = { id = 25521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm With Scorpid", description = "You gotta help me, you just gotta! Chelsea and I came out here to make a bit of money, just sell some supplies, legit work. Next thing I know she's on her deathbed! She's got a fever that'd shock a blacksmith, and she's hallucinating...\n\nShe must've been stung by the scorpids near here! I've seen it happen, it's not pretty. I gotta get some poison glands to make an antidote but I can't leave her side!\n\nPlease, help me! Get me those glands!", progress = "Do you have them? Oh, please...", completion = "Oh thank you, thank you! I know a bit of alchemy, I'm not totally useless. Here goes...", objectives = "Collect 6 Duneclaw Stingers from Duneclaw Scorpids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25522] = { id = 25522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargantapid", description = "No! It didn't work! I don't know what to do, unless...\n\nOh gosh, it's worse than I thought! She must've been stung by the one lurking in the cave. I saw it the first night we arrived. Claws the size of a goblin. A tail as tall as a tree! We shared hushed whispers of it around the campfire... we called it... GARGANTAPID!\n\n ...hey, are you laughing? Stop that! This is serious! Chelsea's life is on the line! Please, I'll make it worth your while...just bring me Gargantapid's poison gland!", progress = "You're back! Do you have it?", completion = "I can't believe it! You're amazing! Here, please, take your reward, take anything you want! I've gotta save Chelsea!", objectives = "Collect Gargantapid's Stinger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25523] = { id = 25523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight in the Firelands", description = "{name}, our enemy is using this grotto in the Firelands to prepare an invasion. We're going to hit them hard right where they live.\n\nBut first, you'll need to get your wings. Flight in the Firelands does not work as it does in the outside world. Something about the dense, superheated air. You'll need some practice!\n\nGet a Twilight Firelance from the rack behind me, equip it, then mount one of Aviana's Guardians. Practice flying - flap your wings! Visit a flag placed on the ledge below and return.", progress = "Do you feel comfortable flying yet?", completion = "Well done! How does it feel?\n\nIt is challenging to master flight in this burning wasteland, but it is the only way.\n\nI hope you're ready for battle, {name}...", objectives = "Get and equip a Twilight Firelance using the rack behind Farden. Mount one of Aviana's Guardians and fly her to the Guardian Flag on the ledge below. Press the flap button to flap your mount's wings!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25524] = { id = 25524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Outhouse", description = "Hello? Hello! HELP!\n\nI'm almost out of air! You have to get me out of here!\n\n<The voice inside gags.>\n\nOne of those Southsea treasure hunters has got to have a crowbar!", progress = "Oh, for the love of the Light, do you have that crowbar yet? Drowning here!", completion = "Thank goodness! Now, just a little shove....", objectives = "Obtain a Pirate's Crowbar and use it to pry open the Submerged Outhouse door.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25525] = { id = 25525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wave One", description = "Here they come, {name}! The Twilight Knight Riders, astride black buzzards birthed in the scorching sulfurous breeding pools of the Firelands. The only way to defeat them is from the sky!\n\nTake wing once more, {class}, and slay them.\n\nRun into enemy riders with your lance to destroy them.\n\nGo forth. Fly, fool. Fly!", progress = "Flap! Flap I say... FLAP!", completion = "Spectacular flying, {name}! Their screeches of anguish echoed about this light-forsaken cavern.\n\nBut our work is not yet finished...", objectives = "Equip a Twilight Firelance and fly Aviana's Guardian. Kill 10 Twilight Knight Riders by flying into them. Press the flap button to flap your mount's wings!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25526] = { id = 25526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Outhouse", description = "Hello? Hello! HELP!\n\nI'm almost out of air! You have to get me out of here!\n\n<The voice inside gags.>\n\nOne of those filthy Southsea treasure hunters has got to have a crowbar!", progress = "Oh, for the love of profit, do you have that crowbar yet? Drowning here!", completion = "Thank goodness! Now, just a little shove....", objectives = "Obtain a Pirate's Crowbar and use it to pry open the Submerged Outhouse door.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25527] = { id = 25527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Replacement Diving Helm" }
quests[25528] = { id = 25528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Replacement Diving Helm" }
quests[25529] = { id = 25529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Replacement Diving Helm" }
quests[25530] = { id = 25530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Replacement Diving Helm" }
quests[25531] = { id = 25531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Riot", description = "I thank you for freeing me.  Let us take advantage of the distraction you've created and get out of here.\n\nWe must hurry before the cultists catch on.\n\nMeet me again when we've left this place.", completion = "You have my thanks, {name}.", objectives = "Speak to Jarod Shadowsong at the Gates of Sothann in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25532] = { id = 25532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirate Accuracy Increasing", description = "I don't know if you've noticed, but the cannonballs are hitting us. I'd say the Southsea pirates are getting more accurate... the ship is on fire!\n\nYou've got a river boat now. Go talk to Mazzer Stripscrew.\n\nPut those fires out!", objectives = "Get a River Boat from Mazzer Stripscrew and then use the Frost Cannon to extinguish 15 fires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25533] = { id = 25533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirate Accuracy Increasing", description = "Oh no, {name}, the cannonballs are hitting the Speedbarge. I'd say the Southsea pirates are getting more accurate... the ship is on fire!\n\nYou've got a river boat now. Please, go speak with Griznak.\n\nExtinguish those fires!", objectives = "Get a River Boat from Griznak and then use the Frost Cannon to extinguish 15 fires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25534] = { id = 25534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Off-Task", description = "As you may have seen, the ship docked to the north has its cannons blazing. While it's pretty fun watching the gnomes run face-first into a hail of iron, my bruisers keep doing it too, and it's absolutely killing my overhead expenses.\n\nI'd like you to try and dance through the cannonfire, get on that ship, and kill the taskmaster leading the cannoneers. The rest of the crew is probably a bunch of spineless prats; once he's down, we should be good.", completion = "Nice work, kid. Any close calls? Did you get grazed?\n\nNo? Good, because we've got more fish to fry here.", objectives = "Kill the Southsea Taskmaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25535] = { id = 25535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Powerful Need To Eat", description = "Poor things. They're starving.\n\nWe've many matters to attend to, not the least of them the naga, but first we need to get some food in these bellies. I'm not sure what the naga fed them up in that shell, if anything, but they're definitely worse for the wear.\n\nQuite a few of the survivors have made their way into Glimmerdeep Gorge, to the northwest. Go join them and help out. With a bit of clam meat, we can get these survivors back on their feet.", completion = "More help! Superb! We can certainly use it, I'll tell you that much.", objectives = "Speak to Divemaster Birmingham in Glimmerdeep Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25536] = { id = 25536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cold Welcome", description = "Many of the survivors made their way down into Glimmerdeep Gorge to help with the clam diving. We've been receiving reports back of deliberate attacks from some kind of murlocs down there.\n\nThe Admiral has to stay here as more men report in from the shell, so I'm having trouble convincing him to get any significant muscle to help the divers. If you'd be up for it, I'm certain they could use your help.\n\nCome back and let me know if you get the situation under control.", completion = "Thank you for stepping up to take care of this, {class}. I know there are a lot of concerns swarming us right now, but maintaining the safety of the survivors is paramount.", objectives = "Kill 10 Glimmerdeep Tidehunters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25537] = { id = 25537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Art of Attraction", description = "I have an idea. A brilliant idea! Those clown-looking fish have developed a symbiotic defensive relationship with the anemones. Having dismissed anemone disguise plausibilities, I've uncovered the chemical attractor that lures the fish.\n\nI have a gyrocoptic thermascrub extractor that I've brought down to take samples. Use it to extract the chemical attractor from several of the anemones, then bring the samples back to me for rapid synthesis and deployment.\n\nGo with haste! Brilliance is waiting!", completion = "Superb! Chemicals abound!\n\nMy instantaneous chemical synthesizer is already pre-tested and prepared. Your deployment compound shall be ready in the blink of an eye!", objectives = "Use the Anemone Chemical Extraction Device to gather 8 Anemone Chemical Samples from the red anemones along the walls of Glimmerdeep Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25538] = { id = 25538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odor Coater", description = "Marvelous creation if I do say so myself. Ready for deployment.\n\nSimply spray the clam divers with a bit of the chemical and they shall soon be accompanied by a protective aquatic companion. You can even spray yourself to similar effect if you so desire.\n\nSpeaking of desire, I would highly recommend that you moderate deployment of the chemical attractor to minimal applications. Large doses could result in undesirable effects...\n\nUndesirable for you anyway. Likely very desirable for the fish.\n\nAway!", progress = "Fishy companions for all!", completion = "Well done my odorific associate. You are both swift and assiduous, if I do say so myself. May your future travels be rampant with inspiration and opulence.", objectives = "Apply the Anemone Chemical Application Device to 8 Clam Divers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25539] = { id = 25539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clamming Up", description = "Here to help with the clam diving?\n\nGet to it then. There are clams about everywhere just waiting to be dived.", progress = "Has your clam-laden frolic proved fruitful?", completion = "Well done, indeed. This is an entirely unshameful amount of clams to have gathered. The survivors back at the cave will surely be grateful.", objectives = "Gather 16 Glimmerdeep Clams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25540] = { id = 25540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bellies Await", description = "We have quite a stock of gathered clams to tote back to the cave, I was simply awaiting someone to do the toting. You've proven dangerous enough to be the sort.\n\nI highly expect that such a fine meal shall not pass uncontested by predators on the way back, so I'd make your trip as swift as possible.\n\nThank you for your help, friend. It's been a pleasure.", progress = "You look to have come back to us with purpose. Was your trip successful?", completion = "This is wonderful. I will begin cooking them immediately. It is good to know that of our many fears, starvation shall no longer need to be one of them.\n\nI imagine the Admiral will have much work for you. Let me trouble you no further for a while.", objectives = "Bring the Hefty Sack Of Clams back to the Tranquil Wash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25541] = { id = 25541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling Our Pockets", description = "We've looted everything that isn't bolted down around here, but I'm not done yet. If we're bothering to do the Steamwheedle Cartel's dirty work for them, we're going to make as much cash as we can while we're here.\n\nI haven't seen many earrings on these pirates, so the gold must be in the next best place...their teeth. The Southsea musketeers and strongarms to the south are the higher-ups here; they'll be the ones with the adornment. Bring me back a good fistful of gold fillings.", progress = "Don't get squeamish on me now.", completion = "Nice!  Remember, gold is gold, no matter who's mouth, nose, or otherwise it's been in.\n\nIt's all perfectly sanitary after being melted down anyway. Or at least wiped off.", objectives = "Collect 20 Gold Fillings from Southsea Musketeers or Southsea Strongarms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25542] = { id = 25542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Circle the Wagons... er, Boats", description = "The fires are dealt with, but there are still Southsea pirates getting ready to board the Speedbarge.\n\nTime to switch to the other side cannon and sink them before it's too late!", completion = "You did it! You did it!\n\n<Jinky grabs you and gives you a big smooch on the cheek! She then regains her dignity and smooths her clothes.>\n\nThanks for saving my Speedbarge, Captain {name}.", objectives = "Sink 15 Southsea Rowboats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25543] = { id = 25543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Circle the Wagons... er, Boats", description = "The fires are dealt with, but there are still Southsea pirates getting ready to board the Speedbarge.\n\nTime to switch to the other side cannon and sink them before it's too late!", completion = "You saved my Speedbarge!\n\n<Razzeric embraces you in a manly hug!>\n\nI can't begin to tell you how relieved I am, Captain {name}!", objectives = "Sink 15 Southsea Rowboats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25544] = { id = 25544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wave Two", description = "You've stirred up the hornets, {name}. The ceiling is coming down on us! And their strongest fighters are taking wing on creatures warped and twisted by this world of flame.\n\nGet back out there and take them down! Watch out for flaming boulders.", progress = "FLAP! For the love of all things merciful, flap. Flap harder!", completion = "By the wings of Aviana - you were born to fly, {name}!\n\nQuickly, let's get back out there and hit them again...", objectives = "Equip a Twilight Firelance and fly Aviana's Guardian. Kill 10 Twilight Lancers by flying into them. Press the flap button to flap your mount's wings!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25545] = { id = 25545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Arms!", description = "As we struggled not to drown, my men and I were forced to abandon our weapons and much of our armor.\n\nErunak says to expect a major attack from the naga soon and I'm inclined to believe him.\n\nIf we're going to stand a chance, we'll need your help to recover our lost armaments. They should be lying on the sea floor near our shipwrecks.\n\nHurry, {race}, we're defenseless here.", progress = "Have you recovered our gear, {race}?", completion = "Well done, {class}!\n\nThanks to you, my men will be ready to confront the enemy when they attack.", objectives = "Gather 4 Stormwind Spears, 4 Stormwind Breastplates, 4 Stormwind Shields and 4 Stormwind Helms.\n\nThe equipment may also be collected from Gliblin Scavengers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25546] = { id = 25546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traveling on Our Stomachs", description = "I'll need your help if I am to get these men ready for battle.\n\nAny decent leader knows that his men travel and fight on their stomachs. No food, no victory.\n\nThese soldiers are weak from their recent ordeal. They'll need sustenance if they're to put up any kind of fight when the need arises.\n\nSpeaking of traveling on stomachs, I've seen several crabs out there on the sea floor....", progress = "Were you able to find anything for my men and I to eat, {class}?", completion = "This should help relieve our exhaustion.\n\nAgain, we thank you.", objectives = "Collect 8 Succulent Crab Meat from Splitclaw Skitterers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25547] = { id = 25547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Our Own Terms", description = "We're as ready as we'll ever be. No sense waiting around for the naga to find us.\n\nI'll address the men, then we'll meet the enemy on our own terms and let fate decide the outcome.", completion = "No time to address the troops now.\n\nJust as well. They know what must be done.", objectives = "Speak to Captain Taylor in the Briny Cutter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25548] = { id = 25548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Firelord", description = "I've been charged with leading our military operations against the enemy.  A humbling task when you consider there are demigods walking among us.\n\nI'm going to have you carry out a series of hit-and-run attacks behind enemy lines.  It will be important that you keep the enemy off guard and weaken their numbers ahead of our main force's attack.\n\nYour first target will be the Ascendant's Rise, where the most highly trained Twilight's Hammer devotees have achieved a partial elemental state.", completion = "You did well, {name}.  I've a new target for you.", objectives = "Slay 4 Flame Ascendants and 5 Twilight Subjugators at the Ascendant's Rise in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25549] = { id = 25549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sanctum of the Prophets", description = "The mad prophets of the Twilight's Hammer congregate in the area just north of the Ascendant's Rise.\n\nIt is said that their dark visions are granted to them directly by the Old Gods.  Whether or not that is true, they provide tremendous spiritual guidance to the cult.  Attacking the Sanctum of the Prophets will deal a devastating blow to the enemy's morale and if we're lucky you might run into one of the Firelord's own emissaries while you're there.", completion = "You continue to prove your prowess, {name}.  At this rate Hyjal might survive this ordeal after all.", objectives = "Slay 4 Twilight Augurs, 4 Twilight Retainers and 1 Emissary of Flame at the Sanctum of the Prophets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25550] = { id = 25550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magma Monarch", description = "The magma giants who serve Ragnaros are kept in line by their king's heavy-handed rule.  Were we to take care of him, the rest will surely fall into disarray.\n\nWithout the giants, the fight on the ground will get a lot more even.  Perhaps even tilt to our favor.\n\nBut felling the magma monarch will be no easy task.  Use these drums to enlist the help of the great Tortolla who is capable of holding off King Moltron for an eternity.  But holding him off won't be enough -- and that's where you come in.", completion = "Excellent work, {name}.  We shall soon claim victory in Hyjal.\n\nIt has been an honor to fight along your side.", objectives = "Use the Drums of the Turtle God to help you defeat King Moltron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25551] = { id = 25551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Firelord", description = "With his gatekeeper gone, you've given the Guardians of Hyjal access to Sulfuron Spire.\n\nRagnaros will have no choice but to defend the main entryway to the Firelands himself.\n\nGo through the Twilight's Hammer portal at the Sanctum of the Prophets and meet me inside.  Malfurion and Hamuul will also aid us while the others continue to fight the enemy outside.", progress = "Yes, {name}?", completion = "Hyjal has been saved, {name}.  And it's all thanks to you.", objectives = "Go through the portal at the Sanctum of the Prophets and aid Cenarius in defeating Ragnaros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25552] = { id = 25552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brood of Evil", description = "This egg you recovered is an alarming sign, {name}.  The Twilight dragons are usually raised from stolen eggs from other dragonflights, which are then modified through dark magic.\n\nThis \"natural\" egg is evidence that one of their matriarchs has become a viable broodmother.  We must destroy her before her brood spreads.\n\nGo to the Ascendant's Rise where they claim these aberrations are kept and slay one of the juvenile drakes.  We will use its skull to lure out its mother.", progress = "You've returned, {race}.", completion = "You've done well, {name}.  We will use this to draw out the Twilight matriarch.", objectives = "Obtain a Young Twilight Drake's Skull at the Ascendant's Rise in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25553] = { id = 25553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Broodmother", description = "We've located the matriarch's feeding grounds south of the Ascendant's Rise.\n\nShe will be extremely angry to have lost one of her drakes.  Place the skull there near the carcasses she devours.  If she's anywhere in the vicinity, she will come out and attempt to exact revenge.\n\nWe will have a surprise waiting for her.", completion = "That went... better than expected.", objectives = "Place the Twilight Drake Skull at the feeding grounds south of the Ascendant's Rise and slay Desperiona.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25554] = { id = 25554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Flame", description = "If we are to banish Ragnaros back into the Firelands, we will need to gain access to Sulfuron Spire.\n\nOnly the most trusted members of the Twilight's Hammer will have been entrusted with such valuable information.\n\nGo search the Ascendant's Rise for any written tomes you might find.  Foul as they are, we cannot waste the opportunity to learn about our enemy's weaknesses.", progress = "Did you succeed in your task, {name}?", completion = "These foul books should not be allowed to exist.  Yet the information inside them is of vital importance.", objectives = "Obtain the Ascendant's Codex, the Burning Litanies and the Tome of Flame at the Ascendant's Rise in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25555] = { id = 25555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gatekeeper", description = "According to these tomes, one of Ragnaros' most powerful lieutenants serves as the sole gatekeeper to Sulfuron Spire.\n\nYou won't be able to defeat him alone.\n\nSound this horn when you engage in combat with Azralon and any of our forces in the vicinity will come to your aid.\n\nYou must hurry, {name}.  It won't be long before the Firelord realizes what we're up to.", progress = "You've returned, {name}?", completion = "It is done.  Only the final step in your mission remains.", objectives = "Use the Horn of Cenarius to help you slay Azralon the Gatekeeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25556] = { id = 25556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Zul'Farrak", description = "That foul traitor...I should've known better than to trust his kind. My hunt for Sul'thraze has blinded me.\n\nForgive me, {name}. Mazoga has fled inside of Zul'Farrak, the heart of the Sandfury civilization.\n\nIf you truly seek the sword, you must pursue him. Do not go alone; the entirety of the Sandfury tribe lies in wait behind those walls, and they will not welcome you.\n\nI will stay here. My search for the blade must end. Should you find it, keep it; I must give up before I am consumed.", completion = "<Mazoga's ghost gives you a blood-smeared grin.>\n\nHow you doin', mon?", objectives = "Find Mazoga within Zul'Farrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25557] = { id = 25557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Ukorz", description = "Take a good look, mon. This is how it goes, betrayal after betrayal. I backstab you for the sword, and then Chief Ukorz go and backstab me even better for it.\n\nThat's life, yah! Or was...\n\nNow, I know you don't got no love for Mazoga. But I know you goin' in there anyway. Kill him for me, mon. Spill more blood on the sand, an' give Chief Ukorz Sandscalp what every one of us in here deserves...a gory death.\n\nMaybe I leave some of my belongin's without a curse before passin' on if you do, yah?", objectives = "Kill Chief Ukorz Sandscalp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25558] = { id = 25558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All or Nothing", description = "This is it.\n\nThis is where we make our stand.\n\nWe must defend this ship to our last breath, and make these cretins think twice before approaching it again!\n\nMay our blades strike fear in their hearts!", completion = "The Earthen Ring has received my distress message and sent help - just in time it would seem.\n\nHopefully more can be sent soon. We are but few against a great many.", objectives = "Assist Captain Taylor in the defense of The Briny Cutter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25559] = { id = 25559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laying Claim", description = "We're not the only ones interested in these ruins, it seem. Of all things, we've got blood elves after our dig sites.\n\nI'd expect them to wilt in the heat without all their fancy fountains and cushy pillows, but they're surprisingly scrappy, and they're trying to drive us out of the Southmoon Ruins by force.\n\nIt's time to crack a few heads. Head over there and teach those elves not to mess with us!", completion = "That'll teach the Horde twofold! Don't mess with dwarven history, and don't send a bunch of frail couch-dwellers to do your fighting!", objectives = "Kill 10 Blood Elf Ruins Hunters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25560] = { id = 25560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Wave", description = "Without any defenders, the Firelands eggs are vulnerable.\n\nTake wing once more and smash those eggs! Simply rush over them to crush them. Search all the nooks, crannies, and side-caves. Hurry!", completion = "A decisive blow!", objectives = "Equip a Twilight Firelance and fly Aviana's Guardian. Smash 40 Firelands Eggs by running over them. Press the flap button to flap your mount's wings!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25561] = { id = 25561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Circle the Wagons... er, Boats", description = "The fires may be dealt with, but those Southsea pirates are still getting ready to board the Speedbarge!\n\n{name}, you need to go back to Mazzer Stripscrew and get on your boat. Use the cannon to sink them before it's too late!", completion = "You did it! You did it!\n\n<Jinky grabs you and gives you a big smooch on the cheek! She then regains her dignity and smooths her clothes.>\n\nThanks for saving my Speedbarge, Captain {name}.", objectives = "Sink 15 Southsea Rowboats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25562] = { id = 25562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Circle the Wagons... er, Boats", description = "The fires may be dealt with, but those Southsea pirates are still getting ready to board the Speedbarge!\n\n{name}, you need to go back to Griznak and get on your boat. Use the cannon to sink them before it's too late!", completion = "You saved my Speedbarge!\n\n<Razzeric embraces you in a manly hug!>\n\nI can't begin to tell you how relieved I am, Captain {name}!", objectives = "Sink 15 Southsea Rowboats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25563] = { id = 25563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", description = "The rift that was here left behind this strange device, but why?\n\nSomeone in a capital city may have more information.", progress = "What's this then?  Another device?", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack!", objectives = "Take the Mysterious Device to Stormwind, Ironforge, Exodar or Darnassus and show it to an Earthen Ring Representative.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25564] = { id = 25564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormwind Elite Aquatic and Land Forces", description = "You've done us a great service, {class}, so I'm going to let you in on a little secret. The men you've saved today aren't your everyday Stormwind troops.\n\nWe belong to a special detachment of elite soldiers sent here not only to contend with the Horde, but to investigate the massive geological disturbances originating from the nearby sea floor.\n\nI tell you this because our top secret equipment lies in the bottom of some of our wrecked ships here.\n\nThat gear must be retrieved!", progress = "Were you able to secure that equipment, {class}?", completion = "Everything here seems to be in working order.", objectives = "Find 6 Stormwind SEAL Equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25565] = { id = 25565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of Language", description = "We've had our first big find in years here at the Southmoon ruins. My lads have dug up stone tablets, engraved with ancient writings.\n\nThe glyphs on the tablets are like nothing we've ever seen, but I have a hunch we can connect them with titanic scripts found at other digsites. Imagine what a breakthrough like that could mean!\n\n I need you to go to the Southmoon ruins and help us collect the tablets; the other lads can't leave, lest the blood elves take our site!", progress = "Do you have the tablets?", completion = "Would you take a look at these...not troll, not qiraji, just pure mystery waiting to be unlocked.\n\nThese aren't going anywhere now that they're safely in our hands. It's time to make our way into the ruins!", objectives = "Collect 5 Ancient Hieroglyphs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25566] = { id = 25566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Uldum", description = "I studied these ruins for years trying to find a way in. We even took a good chunk out of the gate, only to find impenetrable walls beneath. Now the cataclysm may've wrecked everything in there something fierce, but it's done what we couldn't and opened a way in!\n\nI'd like you to have the honor, <lad/lass>. Head on in there and see if anything's been left uncracked. Be careful though... there's no telling what, or who, might be stirring in there.", completion = "This chest lies undisturbed, sealed for thousands of years.", objectives = "Search the Antechamber of Uldum for an intact artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25567] = { id = 25567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", progress = "What's this then?  Another device?\n\nProvided item:", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack!" }
quests[25568] = { id = 25568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", progress = "What's this then?  Another device?\n\nProvided item:", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack!" }
quests[25569] = { id = 25569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", progress = "What's this then?  Another device?\n\nProvided item:", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack!" }
quests[25570] = { id = 25570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", progress = "What's this then?  Another device?\n\nProvided item:", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack!" }
quests[25571] = { id = 25571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Natural Occurrence", description = "This Elemental Shard is all that is left from the rift that stood here before.  The connection between the shard and the rift is unknown, but perhaps someone more versed in the elements would know more.\n\nSeek out an Earthen Ring Emissary in any capital city.  This could be exactly what they are looking for.", progress = "You said you found this near an Elemental Rift?", completion = "Yes, {name}, this shard does explain the occurrence of the rifts.  The elemental planes have been in chaos in Outland ever since Draenor was destroyed. These shards cause a weakness in the already damaged elemental planes and allow the elementals to cross over.\n\nWe're still collecting information on who or what is behind all of this.  However, the more shards you bring me, the better prepared we will be to fight the elemental invasion here in Azeroth.", objectives = "Take the Elemental Shard to an Earthen Ring Emissary in Orgrimmar, Undercity, Thunder Bluff or Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25572] = { id = 25572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", progress = "What's this then?  Another device?\n\nProvided item:", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack!" }
quests[25573] = { id = 25573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Underwater Mount (Temp)", description = "I set up some ropes on the ledge below.  Just tie off your lure to one of the ropes and release it into the abyssal stream. If all goes well, one of the rays should come up for it almost immediately.\n\nI don't expect this to be even remotely easy, so hold on tight and keep an eye ahead at all times. If you should succeed in subduing one of the rays, bring it back here immediately so that we can feed it and cement the bond.\n\nI have a good feeling this time. I think this is it, {name}.", sourceObjective = "Lure and subdue an Abyssal Manta.\n\n[Note: There is a lot pending for this quest - the end result will be much quicker and much cleaner]I set up some ropes on the ledge below. Just tie off your lure to one of the ropes and release it into the abyssal stream. If all goes well, one of the rays should come up for it almost immediately.\n\nI don't expect this to be even remotely easy, so hold on tight and keep an eye ahead at all times. If you should succeed in subduing one of the rays, bring it back here immediately so that we can feed it and cement the bond.\n\nI have a good feeling this time. I think this is it, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25574] = { id = 25574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flames from Above", description = "We've identified the general direction where the infiltrators have been coming from, thanks to your work.\n\nNow we just need to shut down their camp and put an end to their operations this side of Nordrassil.\n\nTake this horn.  It will signal one of our emerald drakes to swoop down and give these Twilight cultists a taste of the flames they so madly worship.", progress = "Is it done yet, {name}?", completion = "Excellent, {name}.  That should put a stop to the attacks once we finish these elementals off.", objectives = "Seek the Twilight Encampment north of Nordrassil and use Tholo's Horn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25575] = { id = 25575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged of Shadow and Flame", description = "The weapons the Twilight's Hammer uses against us are crafted by Forgemaster Pyrenduis within these very halls. The metal slices through armor like cheese in the hands of its wielder. Yet, when captured, the steel turns brittle and shatters.\n\nSo be it, {name}. I'd rather see those cursed arms smashed than delivered to our enemy.\n\nSeek out the crates of Twilight arms in these caverns and smash them to pieces.", completion = "Good, good. I like nothing more than to see the works of our enemy destroyed.", objectives = "Destroy 10 Twilight Arms crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25576] = { id = 25576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage of the Wolf Ancient", description = "Here we are deep within the realm of the fire god and what do we find? The little puppets of Ragnaros, scurrying around to do his bidding.\n\nThese Dark Iron laborers are finishing and packaging the weapons Twilight's Hammer hopes to use in their conquest of Hyjal. I don't care if they're here of their own free will or if they've been brainwashed or kidnapped... They're a foe of our beloved wolf ancient and they should pay the ultimate price.", progress = "It's okay to revel in the destruction of deserving foes, {class}. How goes the fight?", completion = "Dead? Good. They sealed their fate when they threw their lot in with Ragnaros and his kingdom of flame.\n\nLeave their bodies down here to crumble into ash.", objectives = "Slay 12 Dark Iron Laborers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25577] = { id = 25577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Cores", description = "These searing guardians are murderous! We destroy them, and within minutes, they reignite from the ashes.\n\nI think there's a way to destroy them permanently, but we'll need someone who can fight through the front ranks.\n\n{name}, kill the searing guardians and take their smoldering cores to the nearby anvils. Smash them on the Twilight Anvils, and destroy them for good!", progress = "Are they dead?\n\nIt seems like nothing we do can cool this inferno...", completion = "Great work!\n\nThere was a time when adventurers would collect these cores in order to craft mediocre fire-resistant equipment. But for now, I'm glad just to destroy these fiends once and for all.", objectives = "Acquire 8 Smoldering Cores by killing Searing Guardians, then smash them against a Twilight Anvil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25578] = { id = 25578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Nordrassil", description = "I will take Fandral to Moonglade swiftly.  I hope to return soon so I may continue to aid in the battle.\n\nIn the meantime, report back to Ysera and inform her of these recent developments.", completion = "Alysra's decision might not have been the wisest, {name}.  Yet there is little time to worry about that now.\n\nI bring important discoveries from the Emerald Dream.", objectives = "Speak to Ysera at Nordrassil in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25579] = { id = 25579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught Off-Guard", description = "Our escape from the shell can't have gone unnoticed, but either the naga at these ruins weren't informed or they don't consider us a threat. I don't intend to take the opportunity for granted - we strike now.\n\nI need you to slip into the lower level of the ruins to our west and take out as many of their patrols as you can. We cannot risk any of those patrols finding out about our occupation of this cave - make sure none escape.", completion = "Excellent work, {class}.\n\nI will get some of our own patrols out to make sure that no more naga get within sight of this cave. We should have the area secured within the hour.", objectives = "Kill 10 Azsh'ir Patrollers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25580] = { id = 25580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Approach", description = "I've taken the liberty of performing some preliminary scouting. The naga may not be aware of our position, but they are not entirely unprepared for intruders.\n\nBeyond their patrols, they have set up magical sentry devices that will warn them of unwelcome guests. Fortunately, they seem to have sacrificed quality for quantity, and there is definitely a window in which the devices can be destroyed before their alarms are answered.\n\nI trust that you can see to this before our other soldiers arrive.", progress = "It seems clear that they do not take us seriously, which actually worries me. We have no idea how many of these naga there really are. As time passes, I grow to fear that the shell we escaped was only a small piece of a very large puzzle.", completion = "Well done, {name}, and just in time too. The Admiral just started sending more men out. Strong sword arms to be sure, but I doubt they possess quite the same awareness and finesse that you do.\n\nWe were lucky to have you here when things went south. I suspect you will have a large role to play in things to come as well.", objectives = "Destroy 8 Azsh'ir Monitors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25581] = { id = 25581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Occupation of Time", description = "Look--{name} is it?--I need your help. I know most everyone in this cave thinks that we're not in a position to be worrying about anything but our own hides right now, but I cannot dismiss my ancestors so readily.\n\nAll I want from you, while you're out in the city proper, is to keep a watchful eye out for objects of significance. The statues interest me especially.", completion = "Thank you so much for taking this seriously.\n\nThis is some of the first definitive proof of other members of the Vashj family. Very interesting. And I'd never even heard of either of the other two figures you mentioned until now.\n\nSo much of our history was lost during the sundering - it's exciting to have a chance at reclaiming some of it.", objectives = "Investigate the 4 intact statues in the Vashj'ir Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25582] = { id = 25582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Better Vantage", description = "This cave is our only refuge. There's no help on the way. Whatever happens, this cave must remain safe or we are all sure to die down here.\n\nWe need a forward post to launch our attacks from. Something defensible.\n\nIn the eastern portion of the ruins on the lowest level, scout the north end of the gardens, the passage leading under the main structure just west of the gardens, and the cluster of buildings at the southeast corner of the ruins, under the bridges.\n\nBring me back any information you can.", completion = "This is good intel. You have a sharp eye, {class}.\n\nIt sounds like the building tucked under the terrace at the far end of the ruins will make a suitable forward post. I will send some men immediately to start defensive preparations and we will reposition there as soon as possible.", objectives = "On the lowest level of the ruins, scout the northern end of the Quel'Dormir Gardens, the passage that leads under the ruins west of the gardens, and the structures at the southeast corner of the ruins, below the bridges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25583] = { id = 25583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upon the Scene of Battle", description = "All around you lie the remnants of a fierce battle. The naga skeletons are no surprise, but the weapons and remains of their apparent opponents are somewhat more unexpected.\n\nAmidst the bones, you spot a strangely prominent piece of metal jutting out from one of the skulls. It's difficult to tell what sort of weapon it might have once been part of, but it stands out sufficiently to prompt you to retrieve it as evidence.\n\nSurely someone back at the cave would be interested in this revelation.", progress = "Yes, {class}?", completion = "Interesting indeed.\n\nThe remains you describe sound much like the sea vrykul we encountered in Northrend. I highly doubt we will be striking any alliances with their sort, no matter the cause. Still, this information may prove useful in the future.\n\nI will think on it further if time permits. Thank you for bringing it to my attention.", objectives = "Bring the broken shard back to the Tranquil Wash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25584] = { id = 25584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Return of the Ancients", description = "It'll be crucial to reclaim each of the ancients' shrines, {name}.\n\nFollow the road west of the Verdant Thicket, into Wolf's Run.\n\nWe have operatives stationed there.  Aid them in any way that you can and work your way to the first shrine.\n\nThe wolf god was known to the elves as Goldrinn and to the orcs as Lo'Gosh.  He will be a fierce ally in our fight against the enemy.", completion = "Ysera sent you? Good! We need all the help we can.\n\nWe'll never be able to recover the shrines to the ancients so long as Twilight's Hammer controls the roads. Somehow we've got to stem the flood.", objectives = "Speak to Oomla Whitehorn at Wolf's Run in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25585] = { id = 25585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quiet the Cannons", description = "Now it's time to do something about those darn cannons up on the bluffs to the east!\n\nIf you'd be so kind, hop into your boat and cruise on over to the Southsea Holdfast. Up top you'll see a bunch of cannons firing down on us.\n\nThose pirates don't know squat about engineering. It shouldn't be too difficult for you to clog 'em up and make them explode.", completion = "They're still shooting, but not nearly as much! Yeeeeeeeeeaaaaaaaaaaah!", objectives = "Destroy 8 Holdfast Cannons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25586] = { id = 25586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quiet the Cannons", description = "Now it's time to do something about those darn cannons up on the bluffs to the east!\n\nIf you'd be so kind, hop into your boat and cruise on over to the Southsea Holdfast. Up top you'll see a bunch of cannons firing down on us.\n\nThose pirates don't know squat about engineering. It shouldn't be too difficult for you to clog 'em up and make them explode.", completion = "They're still shooting, but not nearly as much! Yeeeeeeeeeaaaaaaaaaaah!", objectives = "Destroy 8 Holdfast Cannons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25587] = { id = 25587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gimme Shelter!", description = "Please, {race}! You must help me!\n\nI've barely managed to survive, what with naga, sharks, and that horrible monster that attacked our ship.\n\nI can see a cave that might be safe, but I don't dare try to make it unless I know there's air inside.\n\nCan you make sure it's ok?", completion = "I cannot thank you enough, {race}.\n\nI just hope this whole nightmare has a happy ending.", objectives = "Investigate Smuggler's Scar in the Kelp'thar forest, then signal to Adarrah that it's safe to enter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25588] = { id = 25588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Payback", description = "It's time for a little payback, I think. Can you blame me? After they locked me down in that outhouse and left me to drown?!\n\nI'll make it worth your while if you head up to the Southsea Holdfast on the eastern bluffs and exact my revenge.", completion = "That'll teach those scurvy dogs! You have my thanks, {name}.", objectives = "Slay 15 Southsea pirates at the Southsea Holdfast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25589] = { id = 25589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Payback", description = "It's time for a little payback, I think. Can you blame me? After they locked me down in that outhouse and left me to drown?!\n\nI'll make it worth your while if you head up to the Southsea Holdfast on the eastern bluffs and exact my revenge.", completion = "That'll teach those scurvy dogs! You have my thanks, {name}.", objectives = "Slay 15 Southsea pirates at the Southsea Holdfast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25590] = { id = 25590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Wizzle?", description = "Hey, {name}, you haven't seen my other brother, Wizzle, have you?\n\nI just know that the pirates captured him! He said that he was going to try to sell them some engineering stuff, or something.\n\nWould you please look for him up at the Southsea Holdfast to the east? I'll bet that no-good goblin he's always traveling with, Synge, got him into trouble!", completion = "Hey! Get me out of here!", objectives = "Find Wizzle Brassbolts at the Southsea Holdfast in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25591] = { id = 25591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderdrome: Grudge Match!", description = "It seems we have a special request! I have here a note from one Megs Dreadshredder, requesting to enter the cage and settle a dispute.\n\nShe's asked for you to be her partner, {name}. A fan of your previous victories? Or perhaps you're acquainted outside the ring?\n\nI wouldn't back down now if I were you. This is the grand finale...", progress = "Stop wasting my time. Enter and fight!", completion = "Fantastic. I might challenge you to a duel myself someday.", objectives = "Defeat Kelsey Steelspark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25592] = { id = 25592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Attraction", description = "I've been able to help some of the survivors make it to the cave, but it's starting to get hairy out there. If we didn't have enough problems, some glowing murlocs started creeping up from the nearby crevice to attack the stranded survivors.\n\nThe men up there are warriors--they won't go down without a fight--but they're much worse for the wear after that damned shell.\n\nIf you have any breath left in your lungs, get up there and take out some of those murlocs. Hellscream's eyes are upon you.", completion = "You know what it is to carry yourself with honor, {class}. You do Hellscream proud.", objectives = "Kill 10 Redgill Scavengers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25593] = { id = 25593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shelled Salvation", description = "A lot of the men haven't made it to the cave yet. It's a safe bet that they're stranded at the vents on the ridge above us.\n\nWe found some spiralung shells on the way here. They don't produce much air, but it was enough for us to make the cave.\n\nI need to stay here to count heads and get them back on their feet as they arrive. Do me a favor - go collect those spiralung shells, get them to any of my men that are still up on the ridge, and give them a swift kick in the arse so that they get moving.", completion = "Thank you, {class}. You've proven very useful.", objectives = "Collect 8 Spiralung shells and give them to stranded Nespirah Survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25594] = { id = 25594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafty Crabs", description = "It was that darn crab!\n\nHere I thought that all the exercise from walking here was making me super buff! My pack just kept getting lighter and lighter. But no! That crab snipped a hole in my bag and all my parts were falling out the whole way here.\n\nPlease, help a good lookin' goblin out, will ya? Go back and help me pick up all of my stray parts. I'm sure those conniving vicious little crabs ran off with some of them too.", progress = "Never underestimate the appeal of something shiny.", completion = "Glad you know a quick buck when you see one. Pleasure doing business with you, buddy.", objectives = "Collect 12 of Fiasco's Stray Parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25595] = { id = 25595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Edible", description = "Were they trying to starve us all to death?! Not giving prisoners food is just despicable.\n\nWe need to get these soldiers fed. The best prospect I spotted on the way here were those giant grouper. Several of those and we shouldn't want for meat for a while.\n\nIf you can bring me back some, I'll see to it that it gets cooked and passed out fairly.", progress = "With all the rumbling bellies, it sounds like there's a monster in this cave. It's putting my nerves on edge.", completion = "Now to hold up my end of the bargain. I'll get this cooked and passed out immediately.\n\nYou and I will have to have a talk later. I'm going to need help that these soldiers just can't offer.", objectives = "Collect 8 Snapjaw Grouper Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25596] = { id = 25596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Synge?", description = "Hey, {name}, you haven't seen our gunsmith, Synge, have you?\n\nI just know that the pirates captured him! He said that he was going to try to sell them some rifles, or something.\n\nWould you please look for him up at the Southsea Holdfast to the east? I'll bet that no-good gnome he's always traveling with, Wizzle Brassbolts, got him into trouble!", completion = "Hey! Get me out of here!", objectives = "Find Synge at the Southsea Holdfast in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25597] = { id = 25597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Jarod Shadowsong", description = "Only once has there been a leader capable of commanding demigods and mortals alike.\n\nHis name was Jarod Shadowsong and his ability to lead in battle was such that Cenarius and the other ancients placed themselves under his command.\n\nHe disappeared for years and his whereabouts were unknown.  Until now.\n\nHe is being held captive inside a Twilight camp in Darkwhisper Gorge.\n\nYour job is to infiltrate their ranks and free Jarod.  Speak to the one known as Ortell at Darkwhisper Pass to the southeast.", completion = "Hey there.  I'm glad to see they sent someone of your caliber for this operation.\n\nThis here's going to call for some subtlety.  We can't risk Commander Shadowsong getting killed.", objectives = "Speak to Elementalist Ortell at Darkwhisper Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25598] = { id = 25598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ain't Too Proud to Beg", description = "Now that you've brought me to safety, I'm afraid I must impose upon your kindness just a bit further.\n\nThe captain of our ship, Samir, is still out there. Mack too. I'm sure they made it to the sea floor but beyond that I didn't see what became of them.\n\nI simply couldn't get by in a place like this without their help.\n\nI lost sight of them in a clump of kelp west of where you found me.\n\nPlease hurry! They couldn't have gotten far...", completion = "Where would we be without you, {race}!\n\nI don't want to even imagine!", objectives = "Find Samir and Mack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25599] = { id = 25599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cindermaul, the Portal Master", description = "Twilight's Hammer is using these corridors, and others like them, to move supplies from the elemental planes up into Azeroth. In order to seal these passages off, we're going to need to know how they're constructed.\n\nFind for me the Tome of Openings, used by the elementals to open gates between the planes.\n\nCindermaul the Portal Master should have one. You'll have to kill him. Careful! He's probably got some tricks up his sleeve...", progress = "The tome! Have you found it?", completion = "This is the tome we've heard about?\n\n<Jordan hefts the stone slab into his arms and looks it over.>\n\nI see... I guess it's good that I can read some of the elemental script. I'll work on translating this. Meanwhile, there's one final problem to take care of.", objectives = "Slay Cindermaul and locate the Tome of Openings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25600] = { id = 25600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgemaster Pyrendius", description = "A terrible evil squats in the heart of this cavern, {name}. Forgemaster Pyrendius has personally crafted many of the cursed weapons that Twilight's Hammer is using in their conquest of the realms above.\n\nBefore we leave these lands of flame... Pyrendius must die.\n\nHe will not go down easy. But, if I'm reading the tome correctly, we can briefly open up small gateways to the Abyssal Maw, the realm of water. Lure Pyrendius onto a portal rune and activate it to weaken him!", progress = "Is Pyrendius dead? This ashen heat of this cave is suffocating me!", completion = "It is done! We'll seal this fiery hole up behind us and let the minions of the Twilight's Hammer discover the corpses we left behind. We couldn't have done it without you, {name}!", objectives = "Slay Forgemaster Pyrendius. Lure him onto the Portal Runes and use them to weaken him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25601] = { id = 25601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head of the Class", description = "That settles it, \"{name}damus!\"  You are head of your class!\n\nYou will get a chance to address a crowd of the most fanatical, bloodthirsty and certifiably insane people on this planet.\n\nGo report to your instructor for the details, but remember: your goal is to exploit the animosity between the ogres at the Seat of the Chosen and the other, less privileged races.\n\nIf all goes well, we will smuggle Jarod out of here during the ensuing riot.", completion = "There you are, Yshkaldamus.  I've been meaning to talk to you about something.\n\nI heard about the unfortunate incident that befell our poor friend, Okrog.\n\n<Mylva looks to her left, then her right.  She finally nods and shoots a sly wink in your direction.>\n\nYou might be a better pupil than I had thought.", objectives = "Speak to instructor Mylva at the Forge of Supplication in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25602] = { id = 25602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Start a Fire Without a Spark", description = "Mack's still out of it, and I fear we may lose him if I can't get this fire started. With the wood being soaked, we'll need something special to get it going.\n\nThere's an abandoned camp nearby with a barrel of explosives in it. There's no way I can recover it on my own.\n\nWould you mind hauling it back for us? For Mack?", progress = "Did you get the explosives from the camp, {class}?", completion = "Outstanding!\n\nLet's see if this does the trick....\n\nStand back, {name}!", objectives = "Get the Keg of Gunpowder from Budd's Dig.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25603] = { id = 25603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", objectives = "Provided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25604] = { id = 25604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", description = "The rift that was here left behind this strange device, but why?\n\nSomeone in a capital city may have more information.", progress = "What's this then?  Another device?", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, bring them to me or one of my associates. We need to learn more about what's behind this attack.", objectives = "Take the Mysterious Device to Stormwind, Ironforge, Exodar or Darnassus and show it to an Earthen Ring Representative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25605] = { id = 25605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", objectives = "Provided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25606] = { id = 25606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", progress = "What's this then?  Another device?\n\nProvided item:", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack!" }
quests[25607] = { id = 25607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ze Gnomecorder", description = "Zese goblinz dizgust me. Zer filzy goblin technology iz inferior to anyzing gnomish, yet...\n\n<Professor Xakxak sighs.>\n\nIt iz ze last piece of ze puzzle! Wizout ze filzy goblin technology ze gnomecorder cannot be built!\n\nVenture eazt into ze \"Skunkworks\" and take from zem zer filzy goblin junk! You vill most likely find zem on goblin technicians.\n\n<Professor Xakxak laughs mockingly.>\n\nGoblin technician? Vut iz zat anyvay?\n\n<Professor Xakxak shrugs.>\n\nZome kind of oxymoron?", progress = "Ze junk? Do you have zit?", completion = "Ah, ze junk haz arrived! Zit is ze last piece of ze puzzle! Now to zet it up! Standby, {name}!", objectives = "Recover 8 pieces of Filthy Goblin Technology.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25608] = { id = 25608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slash and Burn", description = "Victory is possible, {name}.\n\nThis portal is not just a means of bringing back Cenarius through the dream.  Think about it, {name}.  Once a gateway through the Emerald Dream is open, our forces can use them to move freely from Moonglade, Nordrassil, and even Wyrmrest, to this strategic location.\n\nAll Ysera needs is time. It'll be up to you to keep the Twilight's Hammer forces in Darkwhisper Gorge from pulling together and attacking us from the east.\n\nTake one of the emerald drakes and hit them hard, {name}.", progress = "You've returned, {name}.", completion = "Excellent work, {name}.  We might win this one yet.", objectives = "Ride an Emerald Drake and slay 40 Twilight's Hammer units and 5 Twilight Drakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25609] = { id = 25609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "The key to the cage is held by Tony Two-Tusk, the pirate admiral, and he's guarded by ogres that you'll never be able to kill!\n\n<Wizzle cries some more and then looks up, an idea forming in his brain.>\n\nI've got it! What do all pirates want more than anything else? No, not grog. Something even better... treasure!\n\nThey had a ship full of treasure that was sunk by a giant whale-shark. The treasure is scattered all over down in the Mirage Abyss to the northwest.\n\nGo get it!", progress = "Oh gosh, do you already have all of that sunken treasure?", completion = "Oh yeah! Look at all that booty.\n\nWait a minute... bring it closer!", objectives = "Collect 8 Sunken Treasure Chests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25610] = { id = 25610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "The key to the cage is held by Tony Two-Tusk, the pirate admiral, and he's guarded by ogres that you'll never be able to kill!\n\n<Wizzle cries some more and then looks up, an idea forming in his brain.>\n\nI've got it! What do all pirates want more than anything else? No, not grog. Something even better... treasure!\n\nThey had a ship full of treasure that was sunk by a giant whale-shark. The treasure is scattered all over down in the Mirage Abyss to the northwest.\n\nGo get it!", progress = "You already have all of that sunken treasure?", completion = "Oh yeah! Look at all that booty.\n\nWait a minute... bring it closer!", objectives = "Collect 8 Sunken Treasure Chests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25611] = { id = 25611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return from the Firelands", description = "I'll usher out the rest of Goldrinn's followers and seal this portal behind us.\n\nThe rest of our forces at Mount Hyjal will want to hear of this victory. Return to Ian Duran and let him know what we've discovered and how we were triumphant!\n\nSimply step through the portal to return to Mount Hyjal.", completion = "They're moving supplies to Hyjal straight from the elemental planes? That explains so much.\n\nYou've made Goldrinn proud by sealing that flamegate, {name}, but there may be more portals to seal. You should check with the other shrines!", objectives = "Return to Ian Duran at the Shrine of Goldrinn in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25612] = { id = 25612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return from the Firelands", description = "I'll usher out the rest of the followers of Lo'Gosh and seal this portal behind us.\n\nThe rest of our forces at Mount Hyjal will want to hear of this victory. Return to Takrik Ragehowl and let him know what we've discovered and how we were triumphant!\n\nSimply step through the portal to return to Mount Hyjal.", completion = "They're moving supplies to Hyjal straight from the elemental planes? Devious.\n\nYou've made Lo'Gosh proud by sealing that flamegate, {name}, but there may be more portals to seal. You should check with the other shrines!", objectives = "Return to Takrik Ragehowl at the Shrine of Goldrinn in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25613] = { id = 25613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Yourself a Favor", description = "So these night elves send out a desperate call for help to us, goes something like this:\n\n<Gnombus changes the pitch of his voice to sound like a woman.>\n\n\"Please come help us! The big, mean Horde has goblins! Oh, we can't handle goblins! They pull our hair and make us cry!\"\n\nRight, anyway, so here we are.\n\nThe first thing I did was upgrade their aerial defenses with some of my new sniper guns. Problem is, they don't use guns. Do yourself a favor and lend 'em a hand, eh? Find 'em south of here.", completion = "<Kalen sighs.>\n\nWe use guns just fine, friend. CANNONS, on the other hand, I take issue with...", objectives = "Speak to Kalen Trueshot at Trueshot Point in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25614] = { id = 25614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Way Down is in a Body Bag", description = "The skies are swarming with heavily armored orcs on the backs of even more heavily armored wind riders. Our best efforts to bring them down have thus far proven fruitless. Our arrows usually just bounce off of those foul creatures. If we do happen to take one down the orcs deploy their goblin parachutes and safely land on the ground below.\n\nI need you to use Gnombus's sniper cannons and blow up the Warsong wind riders and then blow up the parachuting orcs.\n\nThe only way down is in a body bag.", progress = "We can't get across the pass safely without the wind riders being taken out first.", completion = "Excellent work, {name}. The gnome technology, while somewhat obnoxious, is highly effective. We should now have a clear path to Windshear Hold.", objectives = "Kill 8 Warsong Wing Commanders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25615] = { id = 25615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Stardust", description = "Huntress Jalin will be pleased to know that the way to Windshear Hold is now clear. Please return to Stardust Spire and inform her of your success. She will most assuredly have more work for you now that our path is clear.\n\nThank you and good luck, friend.", completion = "With the airways clear our hippogryphs will be able to move into Stonetalon freely. Well done, {name}!\n\nNow on to more pressing matters. \n\nWhat you witnessed at Trueshot Point was a small sampling of the decimation left in the wake of Hellscream's legacy. As Warchief of the Horde, Hellscream has declared Kalimdor as the Horde's sovereign territory. All that would oppose the Horde are destroyed.\n\nWe are Kalimdor's last line of defense. Should we fall, Kalimdor will also fall. The Horde must be stopped!", objectives = "Return to Huntress Jalin at Stardust Spire in Ashenvale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25616] = { id = 25616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Legacy", description = "Enter Stonetalon Mountains through Talondeep Pass and head towards the smoldering trees. Seek out the Krom'gar incinerators that are destroying the forest and slay as many as you can! Be warned, the incinerators are powerful orcs. Attacking them through conventional means will likely result in your death. Destroy the oil canisters on their backs and they will be devoured by flame!\n\nReport to Sentinel Heliana at Windshear Mine should you succeed. She will have your new orders.", completion = "With the Krom'gar incinerators dealt with, the forest may be allowed to regrow. Only time can heal the wounds left by the Horde.", objectives = "Slay 10 Krom'gar Incinerators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25617] = { id = 25617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Maw!", description = "Atop the Lightning Ledge, the Twilight's Hammer has erected an enormous flamegate. I do not know where it leads; I know it is not of this realm, and I cannot enter. None of my other followers have returned.\n\nI need you to enter this realm and be my fangs within. Step through the flamegate. If he is still alive, meet with Jordan Olafson inside. He will give you a token that will allow you to use my powers in that realm.\n\nBe bold, {name}. Find out where that flamegate leads, and destroy whatever lies within.", completion = "Ah, you are the champion Lo'Gosh promised! Your eyes don't deceive you: you have entered the Firelands, an elemental plane of molten stone and fire. We've got our work cut out for us here.\n\nPut aside your differences with the Alliance, there's plenty of danger to go around.\n\nAnd take this: the Fang of Lo'Gosh will allow you to channel the ancient's power here within the Firelands. Use it well!", objectives = "Step through the flamegate atop the Lightning Ledge in Mount Hyjal, and speak with Jordan Olafson within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25618] = { id = 25618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Maw!", description = "Atop the Lightning Ledge, the Twilight's Hammer has erected an enormous flamegate. I do not know where it leads; I know it is not of this realm, and I cannot enter. None of my other followers have returned.\n\nI need you to enter this realm and be my fangs within. Step through the flamegate. If he is still alive, meet with Jordan Olafson inside. He will give you a token that will allow you to use my powers in that realm.\n\nBe bold, {name}. Find out where that flamegate leads, and destroy whatever lies within.", completion = "Ah, you are the champion Goldrinn promised! Your eyes don't deceive you: you have entered the Firelands, an elemental plane of molten stone and fire. We've got our work cut out for us here.\n\nPut aside your differences with the Horde, there's plenty of danger to go around.\n\nAnd take this: the Fang of Goldrinn will allow you to channel the ancient's power here within the Firelands. Use it well!", objectives = "Step through the flamegate atop the Lightning Ledge in Mount Hyjal, and speak with Jordan Olafson within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25619] = { id = 25619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reoccupation", description = "There's no shortage of Kvaldir to slaughter. They're obviously still reeling from our assault.  The city has been desolate so long, I doubt they expected any naga to contest them here.\n\nThere have been no reports yet of their leader. I'm sure that culling them further will force the coward to rear his head soon enough.\n\nShall we continue?", progress = "I had heard tales of the fierceness of these Kvaldir, but so far, the boasts seem empty.", completion = "Hah! It seems you were right. That broken trident is serving you just fine. I suppose I don't get to see you claw anything to death today after all.", objectives = "Kill 10 Kvaldir defenders in the Ruins of Vashj'ir.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25620] = { id = 25620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Revered Lady", description = "The Revered Lady has sent word for you. She awaits you at the far end of the temple gardens.\n\nIf you feel the need to mention the heroic exploits of your faithful battle brother, Azjentus, please don't hold back. I won't take your admiration of me as a weakness.\n\nI'll hold you up no longer. The Lady awaits.", completion = "Ah, my battlemaiden, you've come to me. The warrior caste whispers of nothing but your victories on the battlefield, and we've only just begun our assault to take the city.\n\nYou have served me proud thus far. May the Queen favor you that you might continue to do more of the same.", objectives = "Speak to Lady Naz'jar at the north end of the Quel'Dormir Gardens.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25621] = { id = 25621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Test: Gnomecorder", description = "Ze Gnomecorder iz complete! Now ve must test zit!\n\nVenture into Stonetalon Mountains to ze southeast and valk down ze Talondeep Pass until you reach a filzy goblin drill machine. I vill activate ze Gnomecorder ven you reach your destination!", completion = "<The Gnomecorder crackles and pops with static electricity.>\n\nCome in, {name}. Can you hear me? Zis iz Professor Xakxak!\n\n*POP*\n\n*CRACKLE*\n\nPERFECT! Viz ze Gnomecorder I vill be able to direct you about Stonetalon vile staying out of harmz vay!\n\nNow, onto our next order of buziness!", objectives = "Enter Stonetalon Mountains and travel south along the Talondeep Pass until you arrive at a goblin drill machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25622] = { id = 25622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn, Baby, Burn!", description = "Deze orc incinerators zat burn ze forest carry viz zem powerful veaponry! You must kill zem and take zhere flame thrower. Vonce you have ze flame thrower, search ze forest for varsong stockpilez and use ze flame thrower to burn zem down!\n\nBurn zem all and I vill reward you! Yes, ze Gnomecorder can transport items!\n\nVait! Do you hear zat! I zink zhere iz an orc nearby! Vatchout!", completion = "<The Gnomecorder buzzes loudly.>\n\nVonderful! As promised, VOILA, your reward!\n\nNow, I have a bit of news that you might find interesting.", objectives = "Obtain a Warsong Flame Thrower from a Krom'gar Incinerator and use the Warsong Flame Thrower to destroy 8 Warsong Stockpiles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25623] = { id = 25623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Maw!", description = "{name}, there you are! Goldrinn has a mission that only his champion can accomplish. Atop the Lightning Ledge, Twilight's Hammer has erected a flamegate. We don't know where it leads, but Goldrinn can't enter. The ancient needs you to be his fangs.\n\nStep into the flamegate and talk to Jordan Olafson when you get inside. He'll give you a token to allow you to use Goldrinn's power in that realm. Find out where the flamegate leads!", completion = "Ah, you are the champion Goldrinn promised! Your eyes don't deceive you: you have entered the Firelands, an elemental plane of molten stone and fire. We've got our work cut out for us here.\n\nPut aside your differences with the Horde, there's plenty of danger to go around.\n\nAnd take this: the Fang of Goldrinn will allow you to channel the ancient's power here within the Firelands. Use it well!", objectives = "Step through the flamegate atop the Lightning Ledge in Mount Hyjal, and speak with Jordan Olafson within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25624] = { id = 25624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Maw!", description = "{name}! Lo'Gosh needs you. Atop the Lightning Ledge, Twilight's Hammer has erected a flamegate. We don't know where it leads, but nobody who's gone through has returned. You are to venture inside and be the fangs of Lo'Gosh within.\n\nStep into the flamegate and talk to Jordan Olafson when you get inside. He'll give you a token to allow you to use Lo'Gosh's power inside that realm. Find out where the flamegate leads!", completion = "Ah, you are the champion Lo'Gosh promised! Your eyes don't deceive you: you have entered the Firelands, an elemental plane of molten stone and fire. We've got our work cut out for us here.\n\nPut aside your differences with the Alliance, there's plenty of danger to go around.\n\nAnd take this: the Fang of Lo'Gosh will allow you to channel the ancient's power here within the Firelands. Use it well!", objectives = "Step through the flamegate atop the Lightning Ledge in Mount Hyjal, and speak with Jordan Olafson within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25625] = { id = 25625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piercing the Ruins" }
quests[25626] = { id = 25626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: Rise from the Deep", description = "What you told me of the naga before has been plaguing my mind. Who are these allies they're summoning? Do they really think they can defeat the Tidehunter?\n\nEscaping this cave brings a degree of relief, but our purpose here remains. I'm hoping you will be willing to seek answers from the Battlemaiden one last time.\n\nThere's only one place that I can think of where they would have taken the artifact - the temple atop the ruins. It's sure to be well guarded. Proceed carefully.", completion = "Minions of the Old God? Two very potent foes have joined forces then. Their hope to defeat the Tidehunter may not be so foolish after all.\n\n{name}, we can't let that happen. If Azshara defeats the Tidehunter and takes his power for herself, I'm not sure any number of us could ever hope to oppose her on the seas.\n\nThe first step is clear at least - we need to hunt down the fiend that destroyed our ships. The navy was confident enough to bring in a new fleet, perhaps they have a plan.", objectives = "Witness the concluding story of the Battlemaiden by using her broken blade somewhere in the Temple of Quel'Dormir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25627] = { id = 25627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two-Tusk Takedown", description = "This treasure's all fake, but it's not like those den whompers are going to know the difference. Stupid ogres!\n\nHere's the plan... you head into the Admiral's Den and spread all of this \"treasure\" around to any ogres that get in your way. Then all you have to do is confront Tony Two-Tusk.\n\nYou'll have the key to the cage in no-time!", progress = "What's going on? You gonna get me out of here?", completion = "Yeah, yeah, yeah... I'm sure that your little adventure into the cave was very interesting.\n\nHow about we talk about it over drinks back on the Speedbarge once you get me out of this cage?", objectives = "Obtain the Rusted Cage Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25628] = { id = 25628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two-Tusk Takedown", description = "This treasure's all fake, but it's not like those den whompers are going to know the difference. Stupid ogres!\n\nHere's the plan... you head into the Admiral's Den and spread all of this \"treasure\" around to any ogres that get in your way. Then all you have to do is confront Tony Two-Tusk.\n\nYou'll have the key to the cage in no-time!", progress = "What's going on? You gonna get me out of here?", completion = "Yeah, yeah, yeah... I'm sure that your little adventure into the cave was very interesting.\n\nHow about we talk about it over drinks back on the Speedbarge once you get me out of this cage?", objectives = "Obtain the Rusted Cage Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25629] = { id = 25629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her Lady's Hand", description = "Battlemaiden!\n\nFind my Honor Guard upon the field of battle and relieve them of their foes. I need them to return to guard the priestesses immediately!\n\nI will hold the entrance. Be swift!", progress = "I dispatched my Honor Guard when the fighting broke out. They are better equipped to deal with the chaos of this kind of battle, and I am hardly in need of their aid.", completion = "Well done, Battlemaiden.\n\nI will attend to the eastern bridge. I need you to attend to the temple itself. The ritual must not be interrupted.", objectives = "Defeat the opponents of 8 Naz'jar Honor Guard on the field of battle and deliver their new orders.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25630] = { id = 25630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fires of Mount Hyjal", description = "Do you see it, {name}? From the ridge southwest of here... plumes of black smoke curling into the sky.\n\nMount Hyjal is burning.\n\nIf the fires have raced this far up the mountain, surely they threaten the Grove of Aessina and all of our forces there. Can you investigate?\n\nSpeak with Laina Nightsky near the Grove of Aessina. Last I heard, she was fighting off the assault.", completion = "Can this wait, {class}? The battle is not going well.\n\nOh, you're here to help. I hope you don't mind a little heat...", objectives = "Speak with Laina Nightsky near the Grove of Aessina in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25631] = { id = 25631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught Off-Guard", description = "I can't imagine that our escape from the shell went unnoticed, but either the naga at these ruins were not informed or don't consider us a threat. I do not intend to take such opportunities for granted - we must strike now.\n\nI need you to slip into the lower level of the ruins and take out as many of their patrols as you can. We cannot risk any of those patrols finding out about our occupation of this cave - make sure none escape.", objectives = "Kill 10 Azsh'ir Patrollers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25632] = { id = 25632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Approach", description = "I've taken the liberty of performing some preliminary scouting. The naga may not be aware of out position, but they are not entirely unprepared for intruders.\n\nBeyond their patrols, they have set up magical sentry devices that will warn them of unwelcome guests. Fortunately, they seem to have sacrificed quality for quantity, and there is definitely a window in which the devices can be destroyed before their alarms are answered.\n\nI trust that you can see to this before our other soldiers arrive.", objectives = "Destroy 10 Azsh'ir Sentry Wards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25633] = { id = 25633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Occupation of Time", description = "Look--{name} is it?--I need your help. I know most everyone in this cave thinks that we're not in a position to be worrying about anything but our own hides right now, but we have an amazing opportunity here.\n\nThis was one of the royal cities of the elves in the days when Azshara was queen. In this city lie the keys to lore long lost and artifacts of unimaginable historical value. All I want from you, while you're out on your little jaunt, is to keep an eye out for exactly those kinds of things.", sourceObjective = "Investigate the 6 in-tact statues in the Vashj'ir Gardens.", sourceObjectiveStatus = "unverified-source-field" }
quests[25634] = { id = 25634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Better Vantage", description = "This cave is our only refuge. There's no place to which we can retreat. There's no help on the way. Whatever happens, this cave must remain safe or we are all sure to die down here.\n\nI have no intention of standing idle. The best way to keep the naga from finding us is to keep them off-balance, but we can't risk them following us back here between strikes. We need a forward post to launch or attacks from.\n\nI'd like you scout the ruins for a suitable base of operation. Something defensible.", objectives = "Scout out the Garden Plaza, the Main Road, and the Temple District.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25635] = { id = 25635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upon the Scene of Battle", description = "All around you lie the remnants of a fierce battle. The naga skeletons are no surprise, but the weapons and remains of their apparent opponents are somewhat more unexpected.\n\nAmidst the bones, you spot a strangely prominent piece of metal jutting out from one of the skulls. It's difficult to tell what sort of weapon it might have once been part of, but it stands out sufficiently to prompt you to retrieve it as evidence.\n\nSurely someone back at the cave would be interested in this revelation.", sourceObjective = "Bring the broken shard back to THE CAVE.", sourceObjectiveStatus = "unverified-source-field" }
quests[25636] = { id = 25636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starve a Fever, Feed a Cold", description = "Mack is fading in and out of consciousness.\n\nIf he's going to make it, he's going to need all the help we can muster.\n\nI know a good recipe for turtle soup that's sure to warm him up.\n\nBring me some turtle meat and I'll handle the rest.", objectives = "Collect 4 Turtle Meats from Speckled Sea Turtles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25637] = { id = 25637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Fathom-Lord's Call", description = "Fathom-Lord Zin'jatar has sent word that the Kvaldir leader has shown himself. I would like you to make your way to him at the far end of the terrace above us, on the middle level of the ruins: Nar'shola Terrace.\n\nKill any Kvaldir that stand in your path on that terrace. We want the echoes of this defeat to ring in their minds so that they will dare not return to threaten our purpose here.\n\nYour devotion does not go unnoticed, my battlemaiden. Go knowing that you have my blessing.", completion = "It is good of you to join me, Battlemaiden. The echoes of your combat graced your approach. It was a beautiful sound to behold.", objectives = "Kill 16 Kvaldir on Nar'shola Terrace, the middle level of the ruins.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25638] = { id = 25638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Desperate Plea", description = "The note in this bottle is soaked through, but still legible.\n\nIn it, the author claims to have escaped from some sort of undersea naga prison.\n\nHe is clearly in fear for his life, and you can't help but wonder if it might be one of your recently abducted shipmates.\n\nAt a loss as to how to locate the escapee, you determine to share the find with Erunak.", completion = "If he still lives, I may be able to locate this poor soul.", objectives = "Take the Soggy Note to Erunak at Shallow's End.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25640] = { id = 25640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs Away: Windshear Mine!", description = "Ve have discovered ze vhereabouts of ze gigantic goblin bomb zat you discovered at Silvervind Refuge.\n\nYou remember Boog? Ze gnome you rescued from ze orcish vagon of agony? Vell, he and Minx have tracked ze bomb down to Windshear Mine. Go zhere immediately, {name}! Zey'll be expecting you.", completion = "Good to see you again, {name}. Thanks for the rescue in Ashenvale. Damn shame about all the gnomes we lost.\n\nYou ready to get down to business?", objectives = "Report to Boog the \"Gear Whisperer\" at Windshear Mine in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25641] = { id = 25641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flow of Muisek", description = "I've done all I can for you. Muisek stronger than the hippogryph just isn't within my power to work with yet, so I won't make you deal with the disaster that could bring.\n\nBut while you've been busy, I've fully readied the hippogryph muisek. Take it to my master, Witch Doctor Uzer'i in Camp Mojache. He can create powerful weapons with it, and hopefully he'll be impressed by what I've done.", progress = "I sense something familiar in your presence...", completion = "Well done indeed... I'd expect nothing less from my own daughter. She'll make a fine witch doctor someday.", objectives = "Deliver the Muisek Vessel to Witch Doctor Uzer'i at Camp Mojache in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25642] = { id = 25642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Look Them in the Eyes", description = "Keep your head down, {name}. No need to draw unwanted attention.\n\nLooks like the orcs are piling that balloon up with some type of ore from the mine. Get in there and take the ore from the orcs. Bring me back whatever you manage to grab and I'll ship it off to the professor for examination.\n\nBefore you go, a word of advice: you can avoid the Krom'gar pretty easily in there as (1) they're dumb as dirt and (2) they can't see anything if they're carrying ore. Of course, you need to kill them to get their ore.", progress = "Get me those ore samples!", completion = "Not too much trouble, I hope. With these samples we should be able to figure out what they plan to do with the ore and the big bomb.", objectives = "Collect 10 Azure Iron Ore samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25643] = { id = 25643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkmist Ruins", description = "I have been beset by visions, {class}. Visions of an icon of great power falling into sinister hands. I see an amulet, held by the ancient elves...sitting forgotten while its surroundings turn to ruins, until it is captured by demons through treachery and malice.\n\nEvery night, these sights flow through my dreams. The spirits are warning us. I am too old, and the camp's braves too occupied with guarding us. I must beseech you to follow my visions to the south, to the Darkmist Ruins, and seek out the amulet.", completion = "<As you reach towards the pedestal, you find it empty. A chill fills the room, and you hear a faint voice...>", objectives = "Search the Darkmist Ruins for the amulet Sage Palerunner described.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25644] = { id = 25644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Egg", description = "The egg is unlike any that you've seen before.  Its translucent shell appears to bend the light around it.\n\nAccompanying it, you find a note describing the arrival of a fertile broodmother at the Ascendant's Rise.\n\nPerhaps you should show this to Aronus.", completion = "You were right to come to me with this, {name}.  This represents a great threat to us if we do not act swiftly and boldly.", objectives = "Take the Pure Twilight Egg to Aronus at the Gates of Sothann in Hyjal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25645] = { id = 25645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sage Palerunner", description = "The soft glow from the pedestal brightens, and you can see a simple chain left behind. This must be the amulet Sage Palerunner sent you here for...", progress = "You've returned. What have you found?", completion = "I am a fool...I was misled. This is nothing more than a rusted trinket, and my visions have no doubt been fulfilled.\n\nForgive me, {name}. But should you meet this demoness again, I pray you will triumph over her as you did Verinias.", objectives = "Bring the Darkmist Amulet to Sage Palerunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25646] = { id = 25646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windshear Mine Cleanup", description = "The Horde has overrun Windshear Mine. I'm not sure what these orcs are hauling out of here or why they're here, but I know that it can't be good. Get in that mine and take out the management. Without goblin overseers, these peons will be even more worthless.\n\nWhile you're inside, keep your eyes peeled for any other information about the Horde operation in the mines.\n\nGood luck!", completion = "Nice job, I could hear their shrill screams from out here. You've turned the whole place on its head!\n\nDid you happen to find any other information about the mining operation?", objectives = "Kill 6 Windshear Overseers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25647] = { id = 25647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illegible Orc Letter", description = "You've discovered a parchment with an impressive looking Horde seal imprinted upon its page. Unfortunately, the rest of the document is completely illegible as it is in orcish.\n\nTake the letter to Boog. He might know what to do with it!", progress = "What have you got there?", completion = "<Boog takes the letter from you and begins to examine it.>\n\nInteresting.\n\n<Boog smells the parchment.>\n\nHrm... Troubling...\n\n<Boog folds the paper in half and looks at you.>\n\nCan't understand a damn thing written here - if that is writing. Could just be toilet paper. Sure smells like it.", objectives = "Take the Illegible Orc Letter to Boog the \"Gear Whisperer\" at Windshear Mine in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25648] = { id = 25648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beyond Durotar", description = "Hmmph... it looks like your services are being requested elsewhere.  Ag'tor Bloodfist is looking for recruits to assist the Horde's ventures in Azshara, north of Orgrimmar.\n\nI'm sure you still have work to do here in Durotar, and I understand that they'll shortly be asking for your help in the Barrens.  I wouldn't be going anywhere yet if I were you, but if you're itching for some manifest destiny... Azshara awaits.", completion = "Good, you're here.  Welcome to Azshara, the stage for the next act of the Horde's glorious future.  Now get to work.", objectives = "Report to Ag'tor Bloodfist at the Orgrimmar Rear Gate in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25649] = { id = 25649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minx'll Fix It", description = "The good news is that Minx is fluent in orcish and she's nearby. Head back into the mine and find her. She's probably deeper inside, standing around being useless.\n\nDon't forget the parchment!", progress = "What have you got there?", completion = "<Minx takes the letter from you and begins to read it.>\n\nUh oh...\n\n<Minx smells the parchment.>\n\nDisgusting!\n\n<Minx folds the paper in half and looks at you.>\n\nThe good news is that this isn't toilet paper. The bad news is that the ink on this paper is a mixture of kodo poop and blood. That's not the worst of it, though...", objectives = "Take the Illegible Orc Letter to Minx inside the Windshear Mine in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25650] = { id = 25650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders from High Command", description = "The letter is actually an order from Horde high command. Someone named Overlord Krom'gar has issued a \"strip job\" on this mine in order to obtain something called azure iron flake. Presumably this flake is obtained from breaking down the ore.\n\nIt gets worse. They plan to mix the azure flake with the explosives sitting inside the huge bomb outside and blow up Windshear Hold.\n\nWe don't have a moment to lose, {name}! Take this translated copy of the letter and return to Boog! He'll know what to do next.", progress = "Well? What's it say?", completion = "<Beads of sweat roll down Boog's overly large forehead as he reads the translated letter.>\n\nThis is bad. Really, really bad. You have to warn Lord Fallowmere at Windshear Hold.\n\nWhat in the... It's MOVING! The goblin balloon is taking off! We're too late!", objectives = "Take the Translated Orc Letter to Boog the \"Gear Whisperer\" at Windshear Mine in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25651] = { id = 25651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, the Insanity!", description = "So, I've been thinkin'...\n\nIf someone's out-of-their-mind-guano-crazy, do they know it?\n\nCase in point, I coulda swore that I'd collected a barrel of gunpowder from the cannonballs around here, but it's nowhere ta be found.\n\nI distinctly remember lifting the cannonballs from them Gilblins just west of here.\n\nMaybe they're right... maybe I really have lost it.", progress = "You want nuthin' to do with me, {race}.\n\nI'm a touch... screwy.", completion = "My gunpowder!\n\nYou found it! I'm not crazy after all!", objectives = "Collect 50 Pilfered Cannonballs from Gurboggle's Ledge and from Gilblin Hoarders. Use the Cannonballs to create a Barrel of Gunpowder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25652] = { id = 25652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commandeer That Balloon!", description = "We don't have a moment to lose, {name}. You're going to have to commandeer that hot air balloon and stop it!\n\nHow? I have no idea! We don't have time to argue details! Grab onto that rope ladder and climb up! Just start banging on stuff once you're inside!\n\nIf you somehow manage to stop the balloon and survive, report to Lord Fallowmere at Windshear Hold in the west.\n\nGood luck, we're all counting on you. Now if you'll excuse me I'm going to RUN FOR MY LIFE!", completion = "Amazing story, lad. I'd have never believed you had I not seen it with my own eyes. You did enough damage to that balloon to make those fiends pull back! Alas, the threat is far from over. We have only delayed the attack. There is much work to do if we are to stop the Horde from destroying Stonetalon!", objectives = "Ride the Krom'gar Hot Air Balloon and attempt to stop it from destroying Windshear Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25653] = { id = 25653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancients are With Us", description = "Nemesis... destroyed.\n\nI feel rejuvenated.\nPowerful.\nAwakened.\n\nTell Ysera my strength is hers.\n\nThe Twilight's Hammer will fall.", completion = "By relieving Tortolla of his final burdens you have acquired for us a formidable ally... and the final piece of the puzzle.\n\nSteel yourself, {name}. The most difficult part of our journey is to begin.\n\nWe will bring the fight to their stronghold.", objectives = "Return to Ysera at Nordrassil in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25654] = { id = 25654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. It is her malicious will that leads the harpies to defend their nests among the ruins of our people.\n\nThe harpies can call to her with a horn they carry - blowing it by the Hatetalon stones, in the northern part of the ruins, will summon Edana.\n\nShow no mercy for these foul creatures. Slay her, and bring her dark heart to me.", progress = "We must not tolerate the infestation of our ancestor's ruins by the harpies.", completion = "These lands will finally be free of the foulness of the harpies. I cannot thank you enough.", objectives = "Slay Edana Hatetalon and obtain Edana's Dark Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25655] = { id = 25655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wormwing Problem", description = "Skylord Omnuron has been too gentle with the Wormwing harpies. He allows them to share a perch on this mountain just because they're creatures of the air. Well {class}, not all creatures of the air are created equal.\n\nWhen the attacks on Hyjal began, the Wormwing went into a frenzy. They're up there right now, assaulting a sacred shrine they once claimed to revere.\n\nI'm not troubled. Now we have a reason to drive them from Hyjal, don't we?", completion = "<Thisalee nods, contentedly, her eyes sparkling.>\n\nFeels great to be off the leash, doesn't it?", objectives = "Slay any combination of 10 Wormwing Harpies (either Screechers or Swifttalons).", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25656] = { id = 25656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrambling for Eggs", description = "There's a pattern to these Wormwing attacks. While groups make a showy assault on the shrine itself, others swoop into the nearby nests and make off with eggs from all the flying creatures of Hyjal.\n\nThese animals are under our protection. Before we find out why the Wormwing are doing this, it's up to us to rescue as many eggs as we can from their talons.", progress = "<Thisalee is cleaning her nails with a dagger. She looks up at you expectantly.>", completion = "Good, that's a start.\n\nThe birds who laid these eggs will never accept them again, so we'll have to raise these birds as orphans in the shrine here. Were Aviana here, she never would've let this travesty happen.\n\nBut, on to business...", objectives = "Gather 8 Hyjal Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25657] = { id = 25657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dah, Nunt... Dah, Nunt...", description = "So, seein' as ya been so kind to me, I'm inclined to let you in on a special secret.\n\nI've found the biggest shiney of all, no more than 50 steps from where we're standin'!\n\nOnly one thing stands between you, me, and great fortune - and his name is Gnaws.\n\nDon't fret now - I've got a plan.\n\nGnaws loves his grubs, so I've loaded one up with that gunpowder so as to make like a trap of sorts, ya see?\n\nJust set it floatin' up in the reef. Once the shark is dead, we're rich!", completion = "Amazing!\n\nYou watch the great white beast swim off into the depths and wonder to yourself if anything could ever take him down...", objectives = "Budd wants you to use the Booby-Trapped Bait at the Rusty Harpoon Gun in the Skeletal Reef.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25658] = { id = 25658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Built to Last", description = "My lady, I have a request from the High Priestess that I am to pass along to you. Many of the city's defenses remain from long before it sunk beneath the waves, and some of them are but a trivial task to reactivate, were it not for the countless Kvaldir that stand in our way.\n\nWe are told you are to be fighting on Nar'shola Terrace above us. You would do my lady a great service if you would but touch some of the devices as you pass. Your noble blood should prove more than sufficient to reactivate them.", completion = "The Nar'shola Wards are performing perfectly. I will inform the Mistress of the Tides of your aid immediately.\n\nThank you for your assistance, my lady.", objectives = "Reactivate 6 Nar'shola Wards on the middle level of the ruins: Narshola Terrace.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25659] = { id = 25659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Soon Forgotten", description = "The Kvaldir leader has shown his rotting, ugly face but a short swim from here, down this hall to our west. We kill him now and the Kvaldir occupation of our once beloved city shall be ended.\n\nBeware Battlemaiden, for he is no weakling. He has many Kvaldir at his command. Some Sira'kess Sea Witches have been dispatched to weaken him during your attack, but they will be interrupted if you let any of his Kvaldir attack them.\n\nShow no mercy, Battlemaiden.", completion = "<The Kvaldir General crumples to the ground, defeated.>\n\n<With this, the ruins of Vashj'ir have been claimed for Lady Naz'jar. Her ultimate goals remain uncertain, but it is clear that the naga came here with purpose.>\n\n<If only you could continue, you are sure that the answers to defeating the naga lie within this vision, but the Wavespeaker's magics are waning, and you are losing your connection with the Battlemaiden.>", objectives = "Kill Varkul the Unrelenting.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25660] = { id = 25660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haunted", description = "You think I'm going to just let you go after you killed me like that, mon? No way! I didn't create a piratical mercantile empire out of nothing just to see you bring me down.\n\nYou're going to help me get back to life. Find my ex-wife, Ajamon, on the north side of the Holdfast. Just follow your nose. She'll be wherever the stinky brewing cauldron is.", completion = "What ya be wantin'? Oh no you don't. I can see ya got Tony's spirit with ya, and I want nothin' to do with it!", objectives = "Speak with Ajamon Ghostcaller at the Southsea Holdfast in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25661] = { id = 25661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With a Little Help...", description = "Fine, I be helpin' ya. He not gettin' outa payin' me alimony that easy! 'Sides, there be the baby he had with me sistah ta take care of!\n\nFirst thing we needin' is the innards of his closest friends. That'd be his cap'ns.\n\nGo down there an' pay the three of them a visit.", progress = "A fresh heart, lungs, an liver be what we needin'. The ones from his cap'ns will have ta do though they all be likely picked.", completion = "<Ajamon makes a face at the state of the organs.>\n\nThey's gonna have ta do. It not be like he had many friends. Ain't that right, Two-Tusk?", objectives = "Collect Evil Dolly's Heart, Seadog Fajardo's Lungs, and Lilly Landlubber's Liver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25662] = { id = 25662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Our Sisters", description = "Yesterday morning I dispatched a squadron of huntresses on a mission into Windshear Crag to obtain information about Horde operations in Stonetalon. Field intelligence reports that they have all been captured, including their squad leader, Huntress Illiona.\n\nHead east into Windshear Crag and slay the Krom'gar infantry that occupy the crag and take from them their keys to unlock the Horde cages holding our sisters.\n\nDo your best to locate Illiona once you've freed the huntresses.", completion = "We don't have much time. To get me out of here you are going to have to take out Warlord Roktrog. He holds the key to this prison.", objectives = "Obtain 5 Horde Cage Keys to free 5 Captured Huntresses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25663] = { id = 25663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Offering for Aviana", description = "Although the guardian of all winged creatures is no longer with us in body, I sometimes hear her voice in the whisper of swaying leaves.\n\n{name}, we ask much of you as you set out to preserve this mountain. Before going on, take a moment to reflect.\n\nTake this offering of nectar to Aviana's burial circle, a circle of stones just outside the main door of the shrine. Perhaps some time alone with Aviana's memory will help sharpen your focus.", progress = "<The spirit fades in and out of your vision, as though here and elsewhere at the same time.>", completion = "<A whispered plea rings within your head.>\n\nTo be born again, but in darkness...\n\nI have been stolen away.\n\n<The spirit appears frantic, but falls silent as her image fades.>", objectives = "Use the Sacred Nectar at Aviana's Burial Circle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25664] = { id = 25664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Prayer and a Wing", description = "A winged visage? Could it be...?\n\n{name}, there's no time to waste. You may have been speaking to Aviana herself, trying to return to us.\n\nI'll need something from Aviana's past to reach out to her. High atop the ridge overlooking this shrine, you'll find a series of huge nests belonging to Blaithe, an ancient bird of prey that was once her consort. For ten thousand years he's been mad with grief.\n\nGo to one of his roosts, and use this call to summon him. Kill Blaithe and bring me one of his feathers.", progress = "Don't trouble yourself over Blaithe's condition. Grief robbed that creature of a soul epochs ago. He was but a shell of his former self, a beast of pure rage.", completion = "That was nasty work, {name}, but it had to be done.\n\nAnd if Aviana is truly to be resurrected, then perhaps your actions have enabled Blaithe to someday come back as well?\n\nNow let's see if we can contact our long lost guardian...", objectives = "Use the Enormous Bird Call at one of Blaithe's Nests perched atop the Rim of the World. Kill Blaithe and gather one of his Ancient Feathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25665] = { id = 25665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plea From Beyond", description = "<You can't make sense of the spirit's urgent plea, but maybe Choluna can decipher what's going on here.>\n\n<Speak with Choluna back inside the shrine!>", completion = "Slow down, {class}! You look as though you've seen a ghost...", objectives = "Return to Choluna inside of the Shrine of Aviana in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25666] = { id = 25666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Your Hands Dirty", description = "Make no mistake, {race}, that is one clever shark. You don't survive down here as long as he has without a little extra smarts.\n\nWhat I'm saying is he won't be fooled so easily again. We're going to have to change our approach a bit.\n\nI won't bore you with the details just yet. For now, I need you to collect a bunch of the innards from these giant sea grubs.\n\nThink you can handle that?", objectives = "Collect 5 Grimy Grub Guts from the Giant Sea Grubs near Harrison's Dig.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25667] = { id = 25667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Wendigos", description = "The wendigos in the Grizzled Den to the southwest of town have long been a thorn in our side. They're never quite strong enough to threaten Kharanos directly, yet they prey on travelers, mountaineer patrols, and supply convoys.\n\nI'm going to be withdrawing my observers from the Grizzled Den because I need them on the troll front. Would you help my men finish culling the wendigo population? Without strength of numbers, they won't be able to attack us.", completion = "Now that you've dealt with the wendigos, we should be able to focus our efforts on the Frostmane trolls to the east.", objectives = "Kill 10 Wendigos in the Grizzled Den. You may kill Wendigos or Young Wendigos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25668] = { id = 25668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfered Supplies", description = "With the Frostmanes making trouble to our east, the wendigos have sensed our weakness and grown bolder in their raids. Only one of the four most recent supply wagons has made it here safely. The wendigos made off with the rest, stashing it in the Grizzled Den, a cave southwest of town. If you're willing to go down there and recover the stolen supplies, you would have the gratitude of all the townspeople and the mountaineers defending Kharanos.", progress = "Did you find any of the missing supplies?", completion = "Well done, {name}. The mountaineers will be glad to hear that half-rations are at an end. They'll need all their strength to continue fighting the Frostmanes.", objectives = "Retrieve 6 Pilfered Supplies from the Grizzled Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25669] = { id = 25669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumble in the Lumber... Mill", description = "Prepare yourself, {name}! The Warlord comes! Kill him and take his key. Use the key to release me.\n\nShould we make it out of here, report the following to Lord Fallowmere at Windshear Hold:\n\nThe Horde has aborted their plans to destroy Windshear Hold due to the efforts of one of our heroes. They now plan to move the bomb to Battlescar Valley and drop it on our armies battling the Horde at that location.\n\nThey must be stopped!", completion = "A hero thwarted their plans to destroy Windshear Hold, eh? That hero was you, {name}. You are the pride of the Alliance!\n\nIt seems that you have bought us a little bit of time. I must plan for the battle that lies ahead of us. Seek out the other inhabitants of Windshear Hold and lend them your assistance. I will call for you when I am ready to initiate our defensive strategy.", objectives = "Kill Warlord Roktrog and free Huntress Illiona by using Huntress Illiona's Cage Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25670] = { id = 25670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DUN-dun-DUN-dun-DUN-dun", description = "If ol' Gnaws had heels he'd be on 'em right now.\n\nFortunately for you, I think like a shark.\n\nGnaws is mad as all get out and we're gunna use that to our advantage.\n\nHere, I found this chain while out treasure-huntin'. Use it to tie off to that harpoon gun.\n\nWhen Gnaws sees ya he'll be consumed with rage - that's when we strike!\n\nYou try to finish him off and I'll sneak in there and grab the shiney.\n\nHurry, {class}, before he grows them teeth back!", completion = "This really ain't as bad as it looks...", objectives = "Use Budd's Chain on the Rusty Harpoon Gun in The Skeletal Reef. Fire the Harpoon when Gnaws is in position over the gun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25671] = { id = 25671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Horde", description = "The Horde's numbers swell as reinforcements from Ashenvale and Azshara arrive. There is no diplomacy to be had with the beasts. This is Hellscream's Horde and Hellscream's Horde wants our blood! We will not sit idly by and allow them to take our land and kill our people. We must act!\n\nWe must thin the Horde! Consider it your daily responsibility.\n\nVenture forth into Stonetalon Mountains and slay as many of the Horde as you are able. Let them know that the Alliance will not surrender!", completion = "Good. Their blood is on Hellscream's hands. Send enough of them back to Orgrimmar in a body bag and the populace of the Horde might react.\n\n<Lord Fallowmere laughs.>\n\nWho am I kidding? They're monsters!", objectives = "Slay any 20 soldiers of the Horde in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25672] = { id = 25672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carcass Collection", description = "These organs be a good start, mon, but we still be needin' lotsa other tings. Normally, we'd be gettin' stuff from family now, but dats only me and my sistah's boy, and Tony ain't worth it!\n\nSo, we be substitutin' some stuff. Lotsa carcasses, in fact!\n\nDeep down in the Shimmering Deep, there's tons of dem from when the water came rushin' in. Killed all of dem creatures. Go down there and bring me up some.", progress = "Ya gots to get me lotsa those carcasses, mon! We not be rid of his foolish spirit if ya don't!", completion = "Oh, that's disgustin'!\n\nWe almost there, mon. Just need ta do one more ting!", objectives = "Collect 10 Creature Carcasses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25673] = { id = 25673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Ask Alice", description = "Mr. P is sick, <mister/miss>. Won't you help him? All you have to do is find his hat and batteries and he'll be all better. I'd go get them myself, but I can't leave Mr. P alone!\n\nHis hat was stolen by the meanies in the Venture Co. over at the water wheel and his batteries are hidden around Windshear Crag. You'll just have to look real hard for those!\n\nWould you kindly bring Mr. P's stuff back so he can teach those baddies in the Horde a lesson?", progress = "Mr. P is so sad. We need to make him happy!", completion = "<Alice claps excitedly.>\n\nMr. P you're gonna be ok! Hooray!\n\n<Alice expertly places all of the parts you collected into Big Papa.>\n\nOh, Mr. P! I knew it!", objectives = "Recover the BD-816 War Apparatus, Mechanized Fire, Mechanized Ice and Mechanized Air.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25674] = { id = 25674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futile Pride", description = "This is actually an old orc city... one of the oldest on Azeroth.  That is, it was until the ogres pushed us out.\n\nToday's Horde refuses to be pushed over by ogres.  My troops and I took the town back by force, and the ogres who once lived here now work as my servants.  Now, our real work begins.\n\nYou look strong enough, but I'd like to see some proof.  Kill one of the ogres that still besiege us, and return to me.", progress = "Is that ogre blood I smell?  It had better be...", completion = "Well done, {race}.  You've proven that you can take down an ogre... no small feat.  Now let's see if you can take down an Alliance iron mine...", objectives = "Kill a Dreadmaul Ambusher in Dreadmaul Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25675] = { id = 25675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Combat", description = "I saw your handiwork down there, {race}.  How'd you like to hunt some more ogres?\n\nWe only enslaved the ones we could catch.  Most of the strongest ogres still brood in Dreadmaul Post, plotting our demise.  Our guards can handle the scattered ambushers, but we are not yet firmly entrenched, and will buckle quickly under a coordinated attack.\n\nGo south to Dreadmaul Post and send a message, {name}.  Slay the strongest before they get any ideas.", completion = "You've done well today, {name}.  Not only have you purchased more time before the next ogre attack, but I think you scared some of the captives into working harder.", objectives = "Slay 6 Dreadmaul Maulers and 5 Dreadmaul Warlocks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25676] = { id = 25676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heartstrike", description = "We don't have any hope of taking the Nethergarde Mines from the Alliance... at least not yet.  Nethergarde is well-defended, and their supply routes are established and strong.  Our goal, then, is to damage their economy.  We can't take the mine by force, but with surgical strikes we can drastically reduce the mine's efficiency.\n\nI have men creating a distraction outside the mines.  Head east, sneak into the mines, and speak with Rofilian Dane for your assignment.", completion = "Finally... another operative shows up.  I hope you're loosened up... it's time to tango, partner.", objectives = "Report to Rofilian Dane at the Nethergarde Mines in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25677] = { id = 25677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All Mine", description = "All over this cavern you'll find unguarded piles of ore, just waiting to be tampered with.  Our first choice would be to steal the ore, obviously, but that requires mine carts, protection, and labor... three things we just don't have.  So instead, we're just going to ruin this little mining party with a little bit of highly corrosive solvent.\n\nTake this bottle - CAREFULLY - and pour it onto those heaps of ore.  'Cause if we can't have this ore, then neither can they.", progress = "I wouldn't store that solvent where I store my potions, if I were you.", completion = "There's nothing quite like a big fat kick in the wallet, is there, you Alliance lunkheads?!", objectives = "Use the Concentrated Solvent on 6 Ore Heaps in the Nethergarde Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25678] = { id = 25678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pick Your Fate", description = "It costs the Alliance approximately fifty gold to train a miner, two hundred to train an engineer, and three hundred to train a foreman.  Every Alliance goon that we kill isn't just a military victory... it's a financial one.\n\nNow get down there and destroy their workers!", completion = "Excellent work, friend.  I like the way you do business.", objectives = "Slay 8 Nethergarde Miners, 3 Nethergarde Engineers, and 3 Nethergarde Foremen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25679] = { id = 25679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Mountain", description = "The next phase of operations takes place deeper within the mine.  Speak with Tak'arili for your next assignment.  Just follow the mine cart rails to the southeast, and follow the curve around.  You'll see him at the entrance to the mine's upper chamber.\n\nIt's been a pleasure doing business with you, {name}.", completion = "Good, you here already.  Stick around for a bit, little {race}.  We gonna mess with the Alliance.\n\nI love my job, mon.", objectives = "Report to Tak'arili deeper within the Nethergarde Mines in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25680] = { id = 25680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Not Us", description = "First things first... it looks like we got ourselves a problem.  These miners down the pathway to the right have been runnin' around like a chickens without they heads on.  My best guess is that they dug too deep and found somethin' nasty... a demon, an elemental, or some kind o' tentacley beast.\n\nTak'arili don't like surprises.  Find out what the problem is and take care of it, then we get ourselves back on track.", completion = "So it was a demon?  Those miners never seen a demon before?  We're in the Blasted Lands, mon!  Demons are everywhere!\n\n<Tak'arili sighs.>\n\nAh well... let's get on to da good stuff, shall we?", objectives = "Find and slay whatever is frightening the miners in the Nethergarde Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25681] = { id = 25681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some People Just Need Killing", description = "The tunnel ahead, headin' west, will take you straight to Chief Prospector Hondo's office.  He's the big cheese around here, and Tak'arili's heard tell that he's a darn fine miner.  That's why he's gotta die.\n\nThere's just one problem: the pathway is completely FILLED with those pesky Nethergarde flunkies.  That's why you gotta disguise yourself.  Hop inside this box here, and sneak down the pathway.  Hopefully you won't draw too much suspicion on your way to da killin'.", progress = "Hondo ain't gonna know what hit him.", completion = "Nice work, mon!  Without Hondo, these guys are helpless.  Dis mine'll be ours soon enough!", objectives = "Slay Chief Prospector Hondo. Use the Inconspicuous Box to disguise yourself along the way.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25682] = { id = 25682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Complete", description = "We be done here, mon.  Only thing left to do is send a report to Okrilla.  You doin' anything right now?", progress = "You've returned, {name}?", completion = "<Okrilla glances over the report.>\n\nImpressive, {name}.  I wouldn't have hidden in that box, but otherwise, you have performed bravely and admirably.  The battle we won today may not win us any immediate spoils, but the damage you've done to the Alliance will last for a long time.", objectives = "Deliver the Nethergarde Mine Report to Okrilla at Dreadmaul Hold in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25683] = { id = 25683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreadmaul Furnace", description = "I meant what I said, {race}.  You helped me, now I'll pass on what I know.\n\nA demon hunter recently came through here, but only briefly.  He was headed south, speaking of demons.  Normally I'd have slain the night elf on sight, but he didn't seem to be Alliance scum, and anybody who kills demons is useful to me for the time being.\n\nYou should check in with Lynnore and Drazial, a pair of blood mages I sent down that way.  They've camped in the back of an ogre cave.", completion = "Okrilla sent you?  Okrilla the killa'?\n\n<Lynnore listens to your tale.>\n\nLoramus was his name?  I'm sorry to say that we have not seen your demon hunter... but we have ways of finding him.", objectives = "Report to Bloodmage Lynnore in the back of the Dreadmaul Furnace in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25684] = { id = 25684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attune the Bloodstone", description = "I admit, we haven't picked the most... convenient of spots to perform our studies, especially for passing adventurers who wish to enter and leave at will.  Our agreement with the ogres is tenuous, and I'm afraid we can't convince them not to attack you when you draw near.\n\nHowever, I can allow you to attune yourself to our bloodstone teleporters.  Simply place your hands on the stone to my right, and you will be teleported outside of the cave.  Then use the stone outside to teleport back!", progress = "The attunement process is simple, but will certainly come in handy down the line.", completion = "Excellent.  Now that that's out of the way...", objectives = "Attune yourself to the Bloodstone Teleporters in the Dreadmaul Furnace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25685] = { id = 25685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Step", description = "To perform the ritual you've requested - and perhaps some more rituals in the near future - we're going to need blood.  The Blasted Lands are filled with every type of reagent we might need for our blood magic... it's just a matter of the correct combination.\n\n<Lynnore quickly confers with Drazial for a moment.>\n\nBasilisks and hyenas, even amounts.  And we're going to need plenty of it.  Head east, to the center of the Blasted Lands.  And don't forget... you can use that teleporter!", progress = "Ogre blood only takes you so far.  Do you have it?", completion = "<Lynnore eyes the blood hungrily.>\n\nMore than enough, and still warm!  Now, let's get this ritual started, shall we?", objectives = "Obtain 9 vials of Snickerfang Hyena Blood and 9 vials of Redstone Basilisk Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25686] = { id = 25686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Ritual", description = "Our goal is to find the demon hunter, Loramus Thalipedes.  Let me know when you are ready to begin the blood ritual, and then stand back.", progress = "The ritual is not yet complete.", completion = "The blood ritual was a success; I can clearly see where Loramus is right now.  That is, I can see where the pieces of his body lie...", objectives = "Speak with Bloodmage Lynnore to begin the blood ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25687] = { id = 25687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Just Any Body", description = "Loramus Thalipedes is dead.  Well, let me step back... that's an assumption on my part, but I do know that his body lies in three pieces.\n\n<Lynnore ponders for a moment.>\n\nIf you bring me the pieces, we still have a recourse.  All three pieces are nearby... the Dreadmaul ogres hide them in their caves.  In fact, one of them is in that chest, down the ledge behind me...", progress = "Trust me... whatever happened to Loramus, we can fix.  The limits of blood magic are still undefined.", completion = "I see... yes, we can work with this.\n\n<Lynnore looks at the night elf's head.>\n\nLoramus Thalipedes, demon hunter.  I look forward to meeting you.", objectives = "Find Loramus' Head, Loramus' Torso, and Loramus' Legs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25688] = { id = 25688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Altar of Storms", description = "Up on the bluffs above our comfy cave is a powerful altar.  A powerful DEMONIC altar, guarded by cultists, but powerful nonetheless.  If you can reach it, you can use it to bring Loramus back to us.\n\nThe altar will likely resist your efforts, so you'll have to protect Loramus' body while the ritual completes.  Bring the demon hunter back to me afterwards.", completion = "You... you fool!  What have you done?", objectives = "Bring Loramus' Body to the Altar of Storms, then protect it while the ritual completes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25689] = { id = 25689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time is Short", description = "I was hunting a demon named Razelikh, when his ogre lieutenant Grol assaulted me.  I was caught unaware, and I died... but so did Grol.\n\nRazelikh plans to return to the Blasted Lands and overwhelm the lands with his demons.  Even now, he is preparing to summon his legions to eliminate us.\n\n<The demon hunter quickly draws a rune in the air, then hands it to you.>\n\nDeliver this to Wazzik at the Dark Portal, to the southeast.  He will guide you.  Quickly!  We haven't much time!", progress = "Do I know you, good {race}?", completion = "What?  LORAMUS?!\n\nOh blast, keep it down, would ya?  If my boss gets word that I worked for Loramus, do you know how quickly I'd be on my rear end?!\n\n<Wazzik takes the rune from you, presses it to his chest, closes his eyes, and nods.>\n\nWell, you weren't lying.  Let's get to work.", objectives = "Deliver the Discordant Rune to Watcher Wazzik at the Dark Portal in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25690] = { id = 25690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bloodmage's Gotta Eat Too", description = "Contrary to popular belief, blood elf bloodmages do NOT drink blood.  We eat normal food like everybody else - something which can be hard to come by in the recesses of an ogre stronghold.\n\nThe ashmane boars in the central valley of the Blasted Lands are, if nothing else, convenient for eating, as their meat does not require any cooking.  Would you hunt these boars and help us replenish our foodstores?", progress = "I'm famished!  If you don't hurry, I might actually resort to drinking our reagents.", completion = "These are perfect, {name}.  Lynnore and I will eat well for the next several days.", objectives = "Obtain 5 Ashmane Steaks from Ashmane Boars in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25691] = { id = 25691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Charred Granite of the Dark Portal", description = "Loramus wants us - er, YOU - to gather granite chips from these chunks of rock around the Dark Portal.  I don't know what he'd want rocks for, but I have my suspicions, and they're not pleasant ones.\n\nUse this pick and look for small outcroppings of rock along the edge of the portal's blast radius.", progress = "Keep it down, would ya?", completion = "I hope this is what he needs.  We probably don't have time for you to return and mine any more.", objectives = "Obtain 24 Charred Granite Chips.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25692] = { id = 25692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vile Blood of Demons", description = "Thalipedes wants demon blood.  Personally, the stuff doesn't even seem like blood to me - more like liquid rot - but that's neither here nor there.\n\nLuckily for you, the area around the Dark Portal is crawling with demons.  Infernals, felhounds, felguards... they've all got what you need, in copious, pustulent amounts.", progress = "Ugh, what's that smell?  Is that you, or the blood?", completion = "There's no doubt about it, you found demon blood.\n\nLoramus' requests aside, I'm sure Dar'toon is thankful for your efforts.  They've been struggling to deal with these demon distractions for some time now.", objectives = "Obtain 7 bottles of Vile Demonic Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25693] = { id = 25693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhancing the Stone", description = "<Wazzik finishes packing the materials up in a neatly-wrapped package.>\n\nThat's all that Loramus asked of us.  When you see him, make sure you let him know how much of a help I was.  I fear he will not see my hand in this.", progress = "{class}... you return...", completion = "This is sufficient.  If you see Wazzik again, you may tell him that he performed satisfactorily.  I will get the bloodmages to work on fashioning the stone knife of sealing.  There is no need for questions now.  All will be revealed in time.\n\nWhile they work, I have another task for you to complete.  Actually, make that three tasks.", objectives = "Bring Wazzik's Package to Loramus Thalipedes at the Dreadmaul Furnace in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25694] = { id = 25694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting Our Rear", description = "The only reason you see me standing aside Alliance soldiers is because our duty outweighs our enmity... however slightly.  We have been charged with protecting the Dark Portal from unauthorized travel, and with the recent cataclysm, we are particularly susceptible to an attack.  We've already heard reports of black dragons in the area...\n\nWith my men focused on their duty, we need someone to keep the area demons in check.  Around the portal you will find three demon lieutenants.  Slay them.", completion = "Your work is appreciated, soldier.\n\n<The warlord leans in close, and whispers:>\n\n{race}... if you're still interested, I have one more small task for you...", objectives = "Kill Jarroc Torn-wing, Shahandana, and Gomegaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25695] = { id = 25695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watching Our Back", description = "<Warlord Dar'toon speaks in hushed tones.>\n\nI have orders from... higher up... that you would be suitable for.  I've seen the Alliance periodically referring to a stack of papers on that barrel over there.  I'd like you to take a look at those papers and find out what it is that they're plotting.  My duty and station prevent me from such a questionable task, but a newcomer like you might be able to slip in unnoticed...", progress = "Did you get a look at those plans, {name}?", completion = "You're certain nobody saw you?  Good.\n\n<Dar'toon listens to your recount of the information you saw.>\n\nHmph... fairly harmless stuff.  Either the Alliance are foolish enough to NOT be planning something against us... or they're hiding their information better than I expected.  Either way, well done, soldier.", objectives = "Examine the Alliance Plans at the Dark Portal without getting caught.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25696] = { id = 25696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunveil Excursion", description = "Oh, right, I received a notification from someone a few days ago.  The Reliquary, was it?  They're looking for someone to... do something...\n\n<The Warlord rifles through some papers.>\n\nAh, here it is!  Yes, Rohan Sunveil of The Reliquary is seeking able-bodied adventurers to assist with an archaeological expedition to the south.\n\nHere, take this with you.  Why don't you go speak with that elf?", completion = "Welcome, traveler.  Thank you for responding to my summons.", objectives = "Report to Rohan Sunveil at the Sunveil Excursion in the Blasted Lands.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25697] = { id = 25697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amulet of Allistarj", description = "When my master helped me to take my eyes out, he gave me the gift of sight... a sight much greater than yours, or even of these blood-craving elves.  My sight allows me to see objects of demonic power, such as the Amulet of Allistarj.\n\nAllistarj himself is dead, but he locked his amulet up in a trove inside the Serpent's Coil, to the east.  Along with the other amulets, this relic will give us access to Razelikh's perch.", progress = "Allistarj left a piece of himself in that amulet.  Even now, I can sense his evil.", completion = "<Lynnore examines the amulet.>\n\nHe was an archmage, I can feel it.  I will hold the amulet for you while you collect the rest.", objectives = "Obtain the Amulet of Allistarj from the Serpent's Coil in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25698] = { id = 25698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amulet of Sevine", description = "Sevine's amulet is in the hands of a murloc, far to the east, on a shelf that overlooks the Shattershore.  How it ended up in that murloc's possession, I cannot say, but I can state with certainty that you will find it there.\n\nI feel a stronger connection with Sevine than with the rest of Razelikh's servants... possibly because she built the Altar of Storms, upon which you resurrected me.  Bring her Amulet to Lynnore, along with the rest.", progress = "Sevine's amulet... along with the others, we can reach the Rise of the Defiler.", completion = "<Lynnore hefts the amulet.>\n\nA warlock... and a powerful one at that.  I will hold onto this until the time is right.", objectives = "Obtain the Amulet of Sevine from Salt-Flop near the Shattershore in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25699] = { id = 25699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Amulet of Grol", description = "Grol... the ogre who tore me apart.\n\n<Loramus laughs.>\n\nIt would seem that Grol's body has changed hands several times since we died together, but it no longer rests with the ogres.  His body, along with his amulet of power, is in a wrecked ship off the Shattershore, to the east.  His amulet is the last... once combined, the three will give us access to Razelikh, and therein lies our chance to stop his madness.", progress = "The third amulet, from Razelikh's third lieutenant.", completion = "<Lynnore clutches the third amulet.>\n\nHe was a powerful warrior, this one.  I will keep the amulet until Loramus is ready to proceed.", objectives = "Obtain Grol's Amulet from the Shattershore in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25700] = { id = 25700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loramus Thalipedes Awaits", description = "The enchantment on these amulets was not complex.  Together, their power will grant you access to Razelikh, the amulets' creator.\n\nI am prepared to perform the ritual on you and Loramus.  Speak with me when you are both ready.", progress = "Speak with Lynnore, and quickly, friend.  This is but the calm before the storm.", completion = "It would seem that we are prepared to face our demon, {name}.  We have the amulet's blessing, we have the stone knife, and I alone know the demon's true name: Rakh'likh.  Together, this may be enough to defeat the Defiler.", objectives = "Speak with Bloodmage Lynnore and participate in her ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25701] = { id = 25701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Are Rakh'likh, Demon", completion = "I see.  So this was Loramus' plan all along.\n\nI suspected correctly, but I suppose I refused to believe it.  And now, his final instruction for me makes much more sense:\n\nHe asked me to let you choose from one of these.", objectives = "Speak with the Deathly Usher north of the Rise of the Defiler. Once atop the Rise, destroy Razelikh's body, then use the Stone Knife of Sealing to imprison his soul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25702] = { id = 25702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home... Gone... Naga...", description = "<The murloc struggles to speak your language.>\n\nRockpool... attacked.  Naga turn, take village, villagers.\n\nSalt-Flop escape, but others do not.  Go south, talk to Chief Neptool.  Maybe he survive.", completion = "<The murloc spirit looks upon you sadly.>\n\nSalt-Flop did not shame himself by running away.  Look behind me, and see for yourself.\n\nThe Rockpool had no hope against the naga's attack.", objectives = "Salt-Flop has asked you to speak with Chief Neptool of the Rockpool murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25703] = { id = 25703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atrocities", description = "<Though his lips do not move, you can feel the murloc chief speaking to you.>\n\nThe Bloodwash naga and the Rockpool murloc have lived among one another for as long as we could remember.  We have always had our differences, but never provoked one another.  Why, then, would they turn on us?\n\n<Neptool looks over his shoulder at his former villagers.>\n\nYou see what they do now?  They enslave us, sacrifice us, force us to fight one another.  I will stop them, {race}... and you will be my weapon.", completion = "You have done well, brave {class}.  I am pleased... but I am not yet satisfied.", objectives = "Slay 10 Bloodwash Barbarians and 10 Bloodwash Enchantresses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25704] = { id = 25704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mad Magus", description = "There's only one ting left dat we can do. Ya gotta slay someone with the big mojo in Tony's presence.\n\nNo, not me!\n\nOl' Magus Tirth went crazy when he tried ta stop the waters rushin' in at the Cataclysm. Now he be hauntin' the area just south of the Holdfast.\n\nTake dis soul stick an' use it on his corpse, mon. Then bring Tony back an' we be gettin' him back in his body.\n\nYa can use me spirit portal ta get down there an' back.", progress = "Ya gotta use the stick on Tirth's corpse if ya gonna help, {name}.", completion = "Now we gonna bring Tony Two-Tusk back ta life. You both ready, mon?", objectives = "Extract the soul of Mad Magus Tirth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25705] = { id = 25705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "False Idols", description = "Neptulon the Tidehunter is our god.  He was the god of the Bloodwash, too, but they have turned their back on him, it seems.  They now choose to worship only Azshara, their naga queen.  You will see likenesses of Azshara littered around their settlements, carved out of seastone.\n\n<The murloc spirit eyes your weapon.>\n\nThat weapon will do.  Send it through their Azsh'ir idols.  They need to be reminded that our father Neptulon is the only one who truly rules the seas.", completion = "You make an old murloc proud, {race}.\n\nThank you, and may the waves ever lap at your feet.", objectives = "Destroy 8 Azsh'ir Idols on the Red Reaches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25706] = { id = 25706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neptool's Revenge", description = "No number of naga deaths will bring back the Rockpool tribe, but any amount of revenge will help the spirits of my people rest more easily.\n\nMany of the more powerful Bloodwash have set up a fortress in the caverns to the northwest.  Slay them, in the name of the Rockpool.  The remaining Bloodwash have erected gladiatorial pools and Azsh'ir altars on our beach, where they pit my people against one another and worship their false god.  Slay them, in the name of the Tidehunter.", completion = "The last Rockpool may be taken hostage today and killed tomorrow, landwalker... but they will pass into the underworld knowing that a brave {race} avenged their death.  Thank you.", objectives = "Slay 8 Bloodwash Acolytes, 8 Bloodwash Zealots, 4 Bloodwash Gamblers, and 4 Bloodwash Idolaters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25707] = { id = 25707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of the Rockpool", description = "The Rockpool tadpoles left upon this crate appear tired, scared, and nearly dried out.  They need to be taken to the water, and quickly.\n\nPerhaps if you can drag this crate across the beach and into the Forbidden Sea, far off the coast of the Red Reaches, then they will have a chance of escaping, and the Rockpool murlocs may live on...", objectives = "Drag the Abandoned Bloodwash Crate to the Forbidden Sea off the coast of the Red Reaches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25708] = { id = 25708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Fallen Friends", description = "Based on what you're telling me, it sounds like there aren't many survivors... just restless spirits.  The least we can do is give them their rest.\n\n<Enohar takes a long draw off of a mug of black ale.>\n\nHead back to the Shattershore and vanquish the worgen ghosts that still remain.  Doing so should release their spirit from this world and allow them to pass into the next.", completion = "<Enohar takes a sip off of a freshly-refilled mug.>\n\nAye, you've done well, lad.  You do the Alliance proud.", objectives = "Kill 13 Drowned Gilneans on the Shattershore to release their spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25709] = { id = 25709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curtail the Darktail", description = "The other thing that concerns me about those shipwrecks is all the vultures that they've attracted.  Knowing how those birds operate, they've already picked the bones clean, but still... we can't allow them to further desecrate the bodies of our friends.\n\nBefore I brewed, I hunted.  Here, take this bow, and more importantly, these arrows.  They've been laced with a little concoction that should give those bonepickers a surprise.", completion = "It's a tragedy, what happened on the Shattershore.  They weren't even soldiers... just people looking for a new home.\n\nI think we've done all we can, {name}.", objectives = "Use Enohar's Explosive Arrows to slay 20 Darktail Bonepickers in the Shattershore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25710] = { id = 25710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minor Distractions", description = "Nethergarde has stood steadfast for years against the demon onslaught that plagues this land.  Our watch is never-ending, our vigilance unfaltering, and our courage bottomless.\n\nWe have held these lands since the portal opened, but now these Horde insects have the insolence to stand in our way!?  We have protected THEM as well as we have protected ourselves!\n\n<Lungertz looks you over.>\n\nLet's see if you've got a hand for combat.  Slay one of the Horde's Okril'lon scouts that nibble at our perimeter.", completion = "Hmm... not bad.  You're quicker than many of my men.  Stick around, {name}... I may have use of you yet.", objectives = "Kill an Okril'lon Scout outside of Nethergarde Keep in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25711] = { id = 25711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Okril'lon", description = "The Horde are a nuisance that we will deal with, but they are proving more difficult than previously expected.  You are to put a stop to this.\n\nTo the west of Nethergarde, the Okril'lon main forces press on our defenses.  They currently hold the Nethergarde Mines, and they mean to move into the supply camps and, eventually, the Keep.  Thin their numbers and delay their advance, {name}.", completion = "You're an excellent asset to the Alliance and the Kirin Tor, {name}.  Well done.\n\nWith time, our forces will retake the mine and press these Horde dogs out of the Blasted Lands.", objectives = "Slay 9 Okril'lon Infantry at the Nethergarde Supply Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25712] = { id = 25712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethergarde Reigns", description = "Lungertz is a strong leader, but he is proud.  He understates the pressure that the Horde is really putting on us.  Without our mine... Nethergarde is penniless.\n\nWe need to move the Horde forces from the supply camp NOW, and doing so means killing their commander, Captain Metlek.  He's not a strong leader, and prefers to bark orders from the back lines, but even so, his death might buy us the victory we need.", completion = "Thank you, {name}.  Thanks to your efforts, I am confident that with time, we will take back the Nethergarde Mine.", objectives = "Slay Captain Metlek at the Nethergarde Supply Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25713] = { id = 25713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remove Their Arms", description = "Say there... {name}, is it?  I've got a proposition for you which involves explosions.  Interested?\n\nI couldn't help but overhear your conversation with the quartermaster.  You see... I've been working on an explosive device.  It's not very effective against other creatures, but devastating against artillery.  If you're heading back into the field to visit those orcs, find some enemy supplies and give this thing a try.  Who knows... maybe they like explosions too.", completion = "Ahh, the sound of things going boom makes my heart pitter-pat.  You've made this gnome's day, {name}.", objectives = "Use Buttonwillow's Hand Grenade on 8 Okril'lon Weapons Crates in the Nethergarde Supply Camp.\n\nMake sure to use the grenades from afar, or you will be blasted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25714] = { id = 25714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watcher Mahar Ba", description = "It's time for you to visit the Watcher.  He's been in a bit of a mood lately, and I'm not quite sure why.\n\nHead up to the top of the mage tower and check in with him.  I don't have any work for you here, but I'm certain that he will.", completion = "My associates were correct to send you to me.  I have a problem which may threaten the sanctity of Nethergarde, and I need someone more capable than most.", objectives = "Report to Watcher Mahar Ba in the mage tower at Nethergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25715] = { id = 25715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Closer Look", description = "We've seen countless ships sail past the shore to the southeast, but most pass by inconspicuously.  Several days ago, however, a powerful storm carried several of the ships to shore and left them wrecked.\n\nI'd bet a pint of Nethergarde Bitter that they were Horde ships if I didn't love Nethergarde Bitter so much.  I can pay you gold, though, if you'll go check out those ships and report back.", progress = "What news from the Shattershore, {name}?", completion = "You saw worgen?  That's bad.\n\nWorgen ghosts?  That's even worse.\n\nThose weren't Horde ships... they were Gilnean.  And they must have been headed down to Surwich, at the bottom of the Tainted Forest.  That makes a lot more sense.\n\nWe've got to try to help them, {name}!  The worgen are our allies!", objectives = "Scout out the crashed ships on the Shattershore in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
